     1→import { useState, useCallback, useMemo } from "react";
     2→import type {
     3→  ActionFunctionArgs,
     4→  HeadersFunction,
     5→  LoaderFunctionArgs,
     6→} from "react-router";
     7→import { useFetcher, useLoaderData, useNavigate } from "react-router";
     8→import { useAppBridge } from "@shopify/app-bridge-react";
     9→import { authenticate } from "../shopify.server";
    10→import { boundary } from "@shopify/shopify-app-react-router/server";
    11→import db from "../db.server";
    12→import { getShopSubscription } from "../billing.server";
    13→import { PLAN_LIMITS } from "../plans";
    14→import {
    15→  Page,
    16→  Layout,
    17→  Card,
    18→  TextField,
    19→  Button,
    20→  Banner,
    21→  BlockStack,
    22→  InlineStack,
    23→  Text,
    24→  Badge,
    25→  DataTable,
    26→  Modal,
    27→  Select,
    28→  Divider,
    29→  EmptyState,
    30→  Box,
    31→  Icon,
    32→  Tooltip,
    33→  CalloutCard,
    34→  DropZone,
    35→  Spinner,
    36→  Pagination,
    37→} from "@shopify/polaris";
    38→import {
    39→  SearchIcon,
    40→  DeleteIcon,
    41→  PlusIcon,
    42→  StarIcon,
    43→  ImportIcon,
    44→  ExportIcon,
    45→} from "@shopify/polaris-icons";
    46→
    47→const PAGE_SIZE = 10;
    48→
    49→export const loader = async ({ request }: LoaderFunctionArgs) => {
    50→  const { session } = await authenticate.admin(request);
    51→  const shop = session.shop;
    52→
    53→  const [zipCodes, subscription] = await Promise.all([
    54→    db.zipCode.findMany({
    55→      where: { shop },
    56→      orderBy: { createdAt: "desc" },
    57→    }),
    58→    getShopSubscription(shop),
    59→  ]);
    60→
    61→  const stats = {
    62→    total: zipCodes.length,
    63→    allowed: zipCodes.filter((z) => z.type === "allowed").length,
    64→    blocked: zipCodes.filter((z) => z.type === "blocked").length,
    65→    active: zipCodes.filter((z) => z.isActive).length,
    66→  };
    67→
    68→  return { zipCodes, stats, subscription };
    69→};
    70→
    71→export const action = async ({ request }: ActionFunctionArgs) => {
    72→  const { session } = await authenticate.admin(request);
    73→  const shop = session.shop;
    74→  const formData = await request.formData();
    75→  const intent = formData.get("intent");
    76→
    77→  if (intent === "add") {
    78→    const zipCode = String(formData.get("zipCode")).trim().toUpperCase();
    79→    const label = String(formData.get("label") || "").trim();
    80→    const zone = String(formData.get("zone") || "").trim();
    81→    const message = String(formData.get("message") || "").trim();
    82→    const eta = String(formData.get("eta") || "").trim();
    83→    const type = String(formData.get("type") || "allowed");
    84→
    85→    if (!zipCode) return { error: "Zip code is required." };
    86→
    87→    const subscription = await getShopSubscription(shop);
    88→    const limits = PLAN_LIMITS[subscription.planTier];
    89→
    90→    if (type === "blocked" && !limits.allowBlocked) {
    91→      return {
    92→        error:
    93→          "Blocked zip codes are not available on the Free plan. Upgrade to Pro or Ultimate.",
    94→        upgradeRequired: true,
    95→      };
    96→    }
    97→
    98→    const currentCount = await db.zipCode.count({ where: { shop } });
    99→    if (limits.maxZipCodes !== Infinity && currentCount >= limits.maxZipCodes) {
   100→      return {
   101→        error: `You have reached the ${limits.maxZipCodes} zip code limit for the Free plan. Upgrade to Pro for unlimited zip codes.`,
   102→        upgradeRequired: true,
   103→      };
   104→    }
   105→
   106→    try {
   107→      await db.zipCode.create({
   108→        data: {
   109→          shop,
   110→          zipCode,
   111→          label: label || null,
   112→          zone: zone || null,
   113→          message: message || null,
   114→          eta: eta || null,
   115→          type,
   116→        },
   117→      });
   118→      return { success: true, action: "added", zipCode };
   119→    } catch {
   120→      return { error: `Zip code "${zipCode}" already exists.` };
   121→    }
   122→  }
   123→
   124→  if (intent === "delete") {
   125→    const id = String(formData.get("id"));
   126→    await db.zipCode.delete({ where: { id } });
   127→    return { success: true, action: "deleted" };
   128→  }
   129→
   130→  if (intent === "toggle") {
   131→    const id = String(formData.get("id"));
   132→    const isActive = formData.get("isActive") === "true";
   133→    await db.zipCode.update({
   134→      where: { id },
   135→      data: { isActive: !isActive },
   136→    });
   137→    return { success: true, action: "toggled" };
   138→  }
   139→
   140→  if (intent === "check") {
   141→    const zipCode = String(formData.get("checkZip")).trim().toUpperCase();
   142→    const found = await db.zipCode.findUnique({
   143→      where: { shop_zipCode: { shop, zipCode } },
   144→    });
   145→    if (!found) return { checkResult: { found: false, zipCode } };
   146→    return { checkResult: { found: true, zipCode, record: found } };
   147→  }
   148→
   149→  if (intent === "bulk-import") {
   150→    const csvData = String(formData.get("csvData") || "");
   151→    if (!csvData.trim()) return { error: "No CSV data provided." };
   152→
   153→    const subscription = await getShopSubscription(shop);
   154→    const limits = PLAN_LIMITS[subscription.planTier];
   155→
   156→    const lines = csvData
   157→      .split("\n")
   158→      .map((l) => l.trim())
   159→      .filter((l) => l.length > 0);
   160→
   161→    // Skip header row if present
   162→    const startIdx =
   163→      lines.length > 0 &&
   164→      lines[0].toLowerCase().includes("zip")
   165→        ? 1
   166→        : 0;
   167→
   168→    const currentCount = await db.zipCode.count({ where: { shop } });
   169→    let imported = 0;
   170→    let skipped = 0;
   171→    const errors: string[] = [];
   172→
   173→    for (let i = startIdx; i < lines.length; i++) {
   174→      const cols = lines[i].split(",").map((c) => c.trim().replace(/^"|"$/g, ""));
   175→      const zipCode = (cols[0] || "").toUpperCase();
   176→      if (!zipCode) continue;
   177→
   178→      const zone = cols[1] || null;
   179→      const type = (cols[2] || "allowed").toLowerCase() === "blocked" ? "blocked" : "allowed";
   180→      const message = cols[3] || null;
   181→      const eta = cols[4] || null;
   182→
   183→      if (type === "blocked" && !limits.allowBlocked) {
   184→        skipped++;
   185→        continue;
   186→      }
   187→
   188→      if (
   189→        limits.maxZipCodes !== Infinity &&
   190→        currentCount + imported >= limits.maxZipCodes
   191→      ) {
   192→        errors.push(
   193→          `Reached the ${limits.maxZipCodes} zip code limit. ${lines.length - startIdx - imported - skipped} zip codes were not imported.`,
   194→        );
   195→        break;
   196→      }
   197→
   198→      try {
   199→        await db.zipCode.upsert({
   200→          where: { shop_zipCode: { shop, zipCode } },
   201→          create: {
   202→            shop,
   203→            zipCode,
   204→            zone,
   205→            type,
   206→            message,
   207→            eta,
   208→          },
   209→          update: {
   210→            zone: zone ?? undefined,
   211→            type,
   212→            message: message ?? undefined,
   213→            eta: eta ?? undefined,
   214→          },
   215→        });
   216→        imported++;
   217→      } catch {
   218→        skipped++;
   219→      }
   220→    }
   221→
   222→    return {
   223→      success: true,
   224→      action: "bulk-import",
   225→      imported,
   226→      skipped,
   227→      errors,
   228→    };
   229→  }
   230→
   231→  if (intent === "export") {
   232→    const zipCodes = await db.zipCode.findMany({
   233→      where: { shop },
   234→      orderBy: { createdAt: "desc" },
   235→    });
   236→
   237→    const header = "Zip Code,Zone,Status,Message,ETA,Active";
   238→    const rows = zipCodes.map(
   239→      (z) =>
   240→        `"${z.zipCode}","${z.zone || ""}","${z.type}","${z.message || ""}","${z.eta || ""}","${z.isActive ? "Yes" : "No"}"`,
   241→    );
   242→    const csv = [header, ...rows].join("\n");
   243→
   244→    return { success: true, action: "export", csv };
   245→  }
   246→
   247→  return null;
   248→};
   249→
   250→type ZipCodeRecord = {
   251→  id: string;
   252→  zipCode: string;
   253→  label: string | null;
   254→  zone: string | null;
   255→  message: string | null;
   256→  eta: string | null;
   257→  type: string;
   258→  isActive: boolean;
   259→  createdAt: string | Date;
   260→};
   261→
   262→export default function ZipCodeCheckerPage() {
   263→  const { zipCodes, stats, subscription } = useLoaderData<typeof loader>();
   264→  const fetcher = useFetcher<typeof action>();
   265→  const shopify = useAppBridge();
   266→  const navigate = useNavigate();
   267→
   268→  const limits = PLAN_LIMITS[subscription.planTier];
   269→  const isFreePlan = subscription.planTier === "free";
   270→  const atZipLimit =
   271→    limits.maxZipCodes !== Infinity && stats.total >= limits.maxZipCodes;
   272→
   273→  // Search & filter state
   274→  const [searchQuery, setSearchQuery] = useState("");
   275→  const [statusFilter, setStatusFilter] = useState("all");
   276→  const [currentPage, setCurrentPage] = useState(1);
   277→
   278→  // Check zip code state
   279→  const [checkZip, setCheckZip] = useState("");
   280→
   281→  // Add modal state
   282→  const [addModalOpen, setAddModalOpen] = useState(false);
   283→  const [newZip, setNewZip] = useState("");
   284→  const [newLabel, setNewLabel] = useState("");
   285→  const [newZone, setNewZone] = useState("");
   286→  const [newMessage, setNewMessage] = useState("");
   287→  const [newEta, setNewEta] = useState("");
   288→  const [newType, setNewType] = useState("allowed");
   289→
   290→  // Import modal state
   291→  const [importModalOpen, setImportModalOpen] = useState(false);
   292→  const [csvText, setCsvText] = useState("");
   293→  const [importFile, setImportFile] = useState<File | null>(null);
   294→
   295→  const isCheckLoading =
   296→    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "check";
   297→  const isAddLoading =
   298→    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "add";
   299→  const isImportLoading =
   300→    fetcher.state !== "idle" &&
   301→    fetcher.formData?.get("intent") === "bulk-import";
   302→
   303→  const checkResult =
   304→    fetcher.data && "checkResult" in fetcher.data
   305→      ? fetcher.data.checkResult
   306→      : null;
   307→  const actionError =
   308→    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
   309→  const upgradeRequired =
   310→    fetcher.data && "upgradeRequired" in fetcher.data
   311→      ? fetcher.data.upgradeRequired
   312→      : false;
   313→  const importResult =
   314→    fetcher.data &&
   315→    "action" in fetcher.data &&
   316→    fetcher.data.action === "bulk-import"
   317→      ? fetcher.data
   318→      : null;
   319→
   320→  // Filtered zip codes
   321→  const filteredZipCodes = useMemo(() => {
   322→    let filtered = zipCodes as ZipCodeRecord[];
   323→
   324→    if (searchQuery.trim()) {
   325→      const q = searchQuery.trim().toLowerCase();
   326→      filtered = filtered.filter(
   327→        (z) =>
   328→          z.zipCode.toLowerCase().includes(q) ||
   329→          (z.zone && z.zone.toLowerCase().includes(q)) ||
   330→          (z.label && z.label.toLowerCase().includes(q)) ||
   331→          (z.message && z.message.toLowerCase().includes(q)),
   332→      );
   333→    }
   334→
   335→    if (statusFilter === "allowed") {
   336→      filtered = filtered.filter((z) => z.type === "allowed");
   337→    } else if (statusFilter === "blocked") {
   338→      filtered = filtered.filter((z) => z.type === "blocked");
   339→    }
   340→
   341→    return filtered;
   342→  }, [zipCodes, searchQuery, statusFilter]);
   343→
   344→  // Pagination
   345→  const totalPages = Math.max(1, Math.ceil(filteredZipCodes.length / PAGE_SIZE));
   346→  const paginatedZipCodes = useMemo(() => {
   347→    const start = (currentPage - 1) * PAGE_SIZE;
   348→    return filteredZipCodes.slice(start, start + PAGE_SIZE);
   349→  }, [filteredZipCodes, currentPage]);
   350→
   351→  // Reset to page 1 when search/filter changes
   352→  const handleSearchChange = useCallback((val: string) => {
   353→    setSearchQuery(val);
   354→    setCurrentPage(1);
   355→  }, []);
   356→
   357→  const handleFilterChange = useCallback((val: string) => {
   358→    setStatusFilter(val);
   359→    setCurrentPage(1);
   360→  }, []);
   361→
   362→  const handleCheck = useCallback(() => {
   363→    if (!checkZip.trim()) return;
