import { useState, useEffect, useCallback } from "react";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import { useFetcher, useLoaderData } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { boundary } from "@shopify/shopify-app-react-router/server";
import { authenticate } from "../shopify.server";
import {
  ALL_PAID_PLANS,
  PLAN_PRO_MONTHLY,
  PLAN_PRO_ANNUAL,
  PLAN_ULTIMATE_MONTHLY,
  PLAN_ULTIMATE_ANNUAL,
} from "../plans";
import {
  syncSubscriptionFromShopify,
  cancelShopSubscription,
  getShopSubscription,
} from "../billing.server";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Divider,
  Box,
  Banner,
  Icon,
  TextField,
} from "@shopify/polaris";
import { CheckCircleIcon } from "@shopify/polaris-icons";

// ─── Plan data ───────────────────────────────────────────────────────────────

const PLANS_DATA = {
  free: {
    id: "free",
    name: "Free",
    monthlyPrice: 0,
    annualPrice: 0,
    annualMonthlyPrice: 0,
    description: "Perfect for new stores looking to get started",
    features: [
      "Up to 25 zip codes",
      "Allowed zip codes only",
      "Basic zip code checker tool",
      "Standard email support",
      "Access to beginner tutorials",
    ],
    shopifyPlanMonthly: null as string | null,
    shopifyPlanAnnual: null as string | null,
  },
  pro: {
    id: "pro",
    name: "Pro",
    monthlyPrice: 12.99,
    annualPrice: 99,
    annualMonthlyPrice: 8.25,
    description: "Tailored for established stores with growing needs",
    features: [
      "Unlimited zip codes",
      "Allowed + Blocked zip codes",
      "Priority email support",
      "Advanced analytics dashboard",
      "Basic API access",
    ],
    shopifyPlanMonthly: PLAN_PRO_MONTHLY,
    shopifyPlanAnnual: PLAN_PRO_ANNUAL,
    bestValue: true,
  },
  ultimate: {
    id: "ultimate",
    name: "Ultimate",
    monthlyPrice: 24.99,
    annualPrice: 199,
    annualMonthlyPrice: 16.58,
    description: "The pinnacle plan for high-volume stores seeking top-tier features",
    features: [
      "Everything from Pro plan",
      "Bulk CSV import",
      "Customizable API endpoints",
      "24/7 VIP support",
      "Exclusive access to beta features",
    ],
    shopifyPlanMonthly: PLAN_ULTIMATE_MONTHLY,
    shopifyPlanAnnual: PLAN_ULTIMATE_ANNUAL,
  },
};

// ─── Loader ───────────────────────────────────────────────────────────────────

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session, billing } = await authenticate.admin(request);
  const shop = session.shop;

  // Sync subscription status from Shopify
  try {
    const billingCheck = await billing.check({
      plans: ALL_PAID_PLANS,
      isTest: process.env.NODE_ENV !== "production",
    });

    const subscription = await syncSubscriptionFromShopify(
      shop,
      billingCheck.appSubscriptions ?? [],
    );

    return { subscription };
  } catch {
    // Fallback to DB
    const subscription = await getShopSubscription(shop);
    return { subscription };
  }
};

// ─── Action ───────────────────────────────────────────────────────────────────

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session, billing } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = String(formData.get("intent"));

  if (intent === "subscribe") {
    const plan = String(formData.get("plan"));
    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;

    try {
      const confirmationUrl = await billing.request({
        plan,
        isTest: process.env.NODE_ENV !== "production",
        returnUrl,
      });
      return { confirmationUrl };
    } catch (err) {
      return { error: "Failed to initiate subscription. Please try again." };
    }
  }

  if (intent === "cancel") {
    try {
      const sub = await getShopSubscription(shop);

      if (sub.shopifySubscriptionId) {
        await billing.cancel({
          subscriptionId: sub.shopifySubscriptionId,
          isTest: process.env.NODE_ENV !== "production",
          prorate: true,
        });
      }

      await cancelShopSubscription(shop);
      return { success: true, message: "Subscription cancelled. You are now on the Free plan." };
    } catch {
      return { error: "Failed to cancel subscription. Please try again." };
    }
  }

  return null;
};

// ─── Component ────────────────────────────────────────────────────────────────

type PlanFeatureProps = { feature: string };

function PlanFeature({ feature }: PlanFeatureProps) {
  return (
    <InlineStack gap="200" blockAlign="start" wrap={false}>
      <Box>
        <Icon source={CheckCircleIcon} tone="success" />
      </Box>
      <Text as="span" variant="bodyMd">
        {feature}
      </Text>
    </InlineStack>
  );
}

type PlanCardProps = {
  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
  isAnnual: boolean;
  currentTier: string;
  onSubscribe: (planName: string) => void;
  onCancel: () => void;
  isLoading: boolean;
};

function PlanCard({
  plan,
  isAnnual,
  currentTier,
  onSubscribe,
  onCancel,
  isLoading,
}: PlanCardProps) {
  const isCurrent = currentTier === plan.id;
  const isBestValue = "bestValue" in plan && plan.bestValue;

  const price = isAnnual ? plan.annualPrice : plan.monthlyPrice;
  const priceLabel = isAnnual ? "/ year" : "/ month";
  const shopifyPlan = isAnnual ? plan.shopifyPlanAnnual : plan.shopifyPlanMonthly;

  const isCurrentPaid = currentTier !== "free";
  const isDowngrade =
    (plan.id === "free" && isCurrentPaid) ||
    (plan.id === "pro" && currentTier === "ultimate");

  let buttonContent = "Get started";
  if (isCurrent) {
    buttonContent = "Current Plan";
  } else if (plan.id === "free") {
    buttonContent = "Downgrade to Free";
  } else if (isDowngrade) {
    buttonContent = `Downgrade to ${plan.name}`;
  } else if (currentTier === "free") {
    buttonContent = "14 days trial";
  } else {
    buttonContent = `Upgrade to ${plan.name}`;
  }

  const handleClick = () => {
    if (isCurrent) return;
    if (plan.id === "free") {
      onCancel();
    } else if (shopifyPlan) {
      onSubscribe(shopifyPlan);
    }
  };

  return (
    <div
      style={{
        flex: 1,
        minWidth: 260,
        maxWidth: 340,
        position: "relative",
        marginTop: isBestValue ? 0 : 20,
      }}
    >
      {isBestValue && (
        <div
          style={{
            position: "absolute",
            top: -16,
            left: "50%",
            transform: "translateX(-50%)",
            zIndex: 1,
            whiteSpace: "nowrap",
          }}
        >
          <div
            style={{
              background: "#1a1a1a",
              color: "#fff",
              padding: "4px 16px",
              borderRadius: 20,
              fontSize: 13,
              fontWeight: 600,
            }}
          >
            Best Value
          </div>
        </div>
      )}

      <div
        style={{
          border: isBestValue ? "2px solid #1a1a1a" : "1px solid #e3e5e7",
          borderRadius: 12,
          padding: 24,
          background: "#fff",
          height: "100%",
          boxSizing: "border-box",
        }}
      >
        <BlockStack gap="400">
          {/* Plan name */}
          <Text as="h3" variant="headingMd" fontWeight="bold">
            {plan.name}
          </Text>

          {/* Price */}
          <InlineStack gap="100" blockAlign="end">
            <Text as="span" variant="headingXl" fontWeight="bold">
              <span style={{ fontSize: 16, verticalAlign: "super" }}>$</span>
              <span style={{ fontSize: 40, lineHeight: 1 }}>{price}</span>
            </Text>
            <Text as="span" tone="subdued" variant="bodySm">
              {priceLabel}
            </Text>
          </InlineStack>

          {/* Description */}
          <Text as="p" tone="subdued" variant="bodySm">
            {plan.description}
          </Text>

          {/* CTA button */}
          <Button
            variant={isCurrent ? "primary" : "secondary"}
            tone={isCurrent ? undefined : plan.id === "free" && isCurrentPaid ? "critical" : undefined}
            onClick={handleClick}
            disabled={isCurrent}
            loading={isLoading}
            fullWidth
          >
            {buttonContent}
          </Button>

          <Divider />

          {/* Features */}
          <BlockStack gap="300">
            {plan.features.map((f) => (
              <PlanFeature key={f} feature={f} />
            ))}
          </BlockStack>
        </BlockStack>
      </div>
    </div>
  );
}

export default function PricingPage() {
  const { subscription } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  const [isAnnual, setIsAnnual] = useState(
    subscription.billingInterval === "annual",
  );
  const [promoVisible, setPromoVisible] = useState(false);
  const [promoCode, setPromoCode] = useState("");

  const isLoading = fetcher.state !== "idle";
  const data = fetcher.data;

  // Redirect to Shopify billing confirmation if returned
  useEffect(() => {
    if (data && "confirmationUrl" in data && data.confirmationUrl) {
      open(data.confirmationUrl as string, "_top");
    }
  }, [data]);

  // Show toast on success/error
  useEffect(() => {
    if (data && "message" in data && data.message) {
      shopify.toast.show(data.message as string);
    }
    if (data && "error" in data && data.error) {
      shopify.toast.show(data.error as string, { isError: true });
    }
  }, [data, shopify]);

  const handleSubscribe = useCallback(
    (planName: string) => {
      const fd = new FormData();
      fd.set("intent", "subscribe");
      fd.set("plan", planName);
      fetcher.submit(fd, { method: "POST" });
    },
    [fetcher],
  );

  const handleCancel = useCallback(() => {
    const fd = new FormData();
    fd.set("intent", "cancel");
    fetcher.submit(fd, { method: "POST" });
  }, [fetcher]);

  const currentTier = subscription.planTier;

  return (
    <Page>
      <Layout>
        <Layout.Section>
          <BlockStack gap="800" align="center">
            {/* Header */}
            <BlockStack gap="200" inlineAlign="center">
              <Text as="h1" variant="headingXl" fontWeight="bold" alignment="center">
                Choose the plan that&apos;s right for you.
              </Text>
              <Text as="p" tone="subdued" variant="bodyMd" alignment="center">
                Start your 14-day free trial today. No credit card required.
              </Text>
            </BlockStack>

            {/* Billing toggle */}
            <InlineStack gap="400" blockAlign="center">
              <div
                style={{
                  display: "flex",
                  background: "#f6f6f7",
                  borderRadius: 8,
                  padding: 4,
                  gap: 4,
                }}
              >
                <button
                  onClick={() => setIsAnnual(false)}
                  style={{
                    padding: "8px 20px",
                    borderRadius: 6,
                    border: "none",
                    cursor: "pointer",
                    fontWeight: 600,
                    fontSize: 14,
                    background: !isAnnual ? "#fff" : "transparent",
                    boxShadow: !isAnnual ? "0 1px 4px rgba(0,0,0,0.12)" : "none",
                    color: "#1a1a1a",
                    transition: "all 0.15s",
                  }}
                >
                  Pay Monthly
                </button>
                <button
                  onClick={() => setIsAnnual(true)}
                  style={{
                    padding: "8px 20px",
                    borderRadius: 6,
                    border: "none",
                    cursor: "pointer",
                    fontWeight: 600,
                    fontSize: 14,
                    background: isAnnual ? "#fff" : "transparent",
                    boxShadow: isAnnual ? "0 1px 4px rgba(0,0,0,0.12)" : "none",
                    color: "#1a1a1a",
                    transition: "all 0.15s",
                  }}
                >
                  Pay Annual{" "}
                  <span style={{ color: "#2c6e49", fontWeight: 700 }}>
                    (Save 20%)
                  </span>
                </button>
              </div>

              <Button
                variant="plain"
                onClick={() => setPromoVisible((v) => !v)}
              >
                Have a promo code?
              </Button>
            </InlineStack>

            {/* Promo code input */}
            {promoVisible && (
              <Card>
                <InlineStack gap="300" blockAlign="end">
                  <div style={{ flex: 1 }}>
                    <TextField
                      label="Promo code"
                      value={promoCode}
                      onChange={setPromoCode}
                      placeholder="Enter promo code"
                      autoComplete="off"
                    />
                  </div>
                  <Button variant="primary">Apply</Button>
                </InlineStack>
              </Card>
            )}

            {/* Error banner */}
            {data && "error" in data && data.error && (
              <Banner tone="critical">{data.error}</Banner>
            )}

            {/* Success banner */}
            {data && "success" in data && data.success && (
              <Banner tone="success">
                {data && "message" in data ? String(data.message) : "Plan updated successfully."}
              </Banner>
            )}

            {/* Plan cards */}
            <div
              style={{
                display: "flex",
                gap: 24,
                alignItems: "flex-start",
                flexWrap: "wrap",
                justifyContent: "center",
                width: "100%",
              }}
            >
              {(Object.values(PLANS_DATA) as (typeof PLANS_DATA)[keyof typeof PLANS_DATA][]).map((plan) => (
                <PlanCard
                  key={plan.id}
                  plan={plan}
                  isAnnual={isAnnual}
                  currentTier={currentTier}
                  onSubscribe={handleSubscribe}
                  onCancel={handleCancel}
                  isLoading={isLoading}
                />
              ))}
            </div>

            {/* Current plan badge */}
            <InlineStack gap="200" blockAlign="center">
              <Text as="p" tone="subdued" variant="bodySm">
                Current plan:
              </Text>
              <Badge
                tone={
                  currentTier === "ultimate"
                    ? "attention"
                    : currentTier === "pro"
                      ? "info"
                      : "enabled"
                }
              >
                {PLANS_DATA[currentTier as keyof typeof PLANS_DATA]?.name ??
                  "Free"}
              </Badge>
            </InlineStack>
          </BlockStack>
        </Layout.Section>
      </Layout>
    </Page>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

