    39→import { CheckCircleIcon } from "@shopify/polaris-icons";
    40→
    41→// ─── Plan data ────────────────────────────────────────────────────────────────
    42→
    43→const PLANS_DATA = {
    44→  free: {
    45→    id: "free",
    46→    name: "Free",
    47→    monthlyPrice: 0,
    48→    annualPrice: 0,
    49→    annualMonthlyPrice: 0,
    50→    description: "Perfect for new stores getting started",
    51→    features: [
    52→      "Up to 25 zip codes",
    53→      "Allowed zip codes only",
    54→      "Basic storefront widget",
    55→      "Standard email support",
    56→    ],
    57→    shopifyPlanMonthly: null as string | null,
    58→    shopifyPlanAnnual: null as string | null,
    59→  },
    60→  pro: {
    61→    id: "pro",
    62→    name: "Pro",
    63→    monthlyPrice: 12.99,
    64→    annualPrice: 99,
    65→    annualMonthlyPrice: 8.25,
    66→    description: "For growing stores that need more control",
    67→    features: [
    68→      "Unlimited zip codes",
    69→      "Allowed + Blocked zip codes",
    70→      "Delivery zones & ETAs",
    71→      "Bulk CSV import & export",
    72→      "Customer waitlist",
    73→      "Priority email support",
    74→    ],
    75→    shopifyPlanMonthly: PLAN_PRO_MONTHLY,
    76→    shopifyPlanAnnual: PLAN_PRO_ANNUAL,
    77→    bestValue: true,
    78→  },
    79→  ultimate: {
    80→    id: "ultimate",
    81→    name: "Ultimate",
    82→    monthlyPrice: 24.99,
    83→    annualPrice: 199,
    84→    annualMonthlyPrice: 16.58,
    85→    description: "For high-volume stores needing top-tier features",
    86→    features: [
    87→      "Everything in Pro",
    88→      "Advanced delivery rules",
    89→      "Customisable widget CSS",
    90→      "API access",
    91→      "24/7 VIP support",
    92→      "Early access to new features",
    93→    ],
    94→    shopifyPlanMonthly: PLAN_ULTIMATE_MONTHLY,
    95→    shopifyPlanAnnual: PLAN_ULTIMATE_ANNUAL,
    96→  },
    97→};
    98→
    99→// ─── Loader ───────────────────────────────────────────────────────────────────
   100→
   101→export const loader = async ({ request }: LoaderFunctionArgs) => {
   102→  const { session, billing } = await authenticate.admin(request);
   103→  const shop = session.shop;
   104→
   105→  try {
   106→    const billingCheck = await billing.check({
   107→      plans: ALL_PAID_PLANS,
   108→      isTest: process.env.NODE_ENV !== "production",
   109→    });
   110→    const subscription = await syncSubscriptionFromShopify(
   111→      shop,
   112→      billingCheck.appSubscriptions ?? [],
   113→    );
   114→    return { subscription };
   115→  } catch {
   116→    const subscription = await getShopSubscription(shop);
   117→    return { subscription };
   118→  }
   119→};
   120→
   121→// ─── Action ───────────────────────────────────────────────────────────────────
   122→
   123→export const action = async ({ request }: ActionFunctionArgs) => {
   124→  const { session, billing } = await authenticate.admin(request);
   125→  const shop = session.shop;
   126→  const formData = await request.formData();
   127→  const intent = String(formData.get("intent"));
   128→
   129→  if (intent === "subscribe") {
   130→    const plan = String(formData.get("plan"));
   131→    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;
   132→    try {
   133→      const confirmationUrl = await billing.request({
   134→        plan,
   135→        isTest: process.env.NODE_ENV !== "production",
   136→        returnUrl,
   137→      });
   138→      return { confirmationUrl };
   139→    } catch {
   140→      return { error: "Failed to initiate subscription. Please try again." };
   141→    }
   142→  }
   143→
   144→  if (intent === "cancel") {
   145→    try {
   146→      const sub = await getShopSubscription(shop);
   147→      if (sub.shopifySubscriptionId) {
   148→        await billing.cancel({
   149→          subscriptionId: sub.shopifySubscriptionId,
   150→          isTest: process.env.NODE_ENV !== "production",
   151→          prorate: true,
   152→        });
   153→      }
   154→      await cancelShopSubscription(shop);
   155→      return {
   156→        success: true,
   157→        message: "Subscription cancelled. You are now on the Free plan.",
   158→      };
   159→    } catch {
   160→      return { error: "Failed to cancel subscription. Please try again." };
   161→    }
   162→  }
   163→
   164→  return null;
   165→};
   166→
   167→// ─── Feature row ─────────────────────────────────────────────────────────────
   168→
   169→function PlanFeature({ feature }: { feature: string }) {
   170→  return (
   171→    <InlineStack gap="200" blockAlign="start" wrap={false}>
   172→      <Box>
   173→        <Icon source={CheckCircleIcon} tone="success" />
   174→      </Box>
   175→      <Text as="span" variant="bodyMd">
   176→        {feature}
   177→      </Text>
   178→    </InlineStack>
   179→  );
   180→}
   181→
   182→// ─── Plan card ────────────────────────────────────────────────────────────────
   183→
   184→type PlanCardProps = {
   185→  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
   186→  isAnnual: boolean;
   187→  currentTier: string;
   188→  onSubscribe: (planName: string) => void;
   189→  onRequestCancel: () => void;
   190→  loadingPlan: string | null;
   191→};
   192→
   193→function PlanCard({
   194→  plan,
   195→  isAnnual,
   196→  currentTier,
   197→  onSubscribe,
   198→  onRequestCancel,
   199→  loadingPlan,
   200→}: PlanCardProps) {
   201→  const isCurrent = currentTier === plan.id;
   202→  const isBestValue = "bestValue" in plan && plan.bestValue;
   203→  const isCurrentPaid = currentTier !== "free";
   204→  const isDowngrade =
   205→    (plan.id === "free" && isCurrentPaid) ||
   206→    (plan.id === "pro" && currentTier === "ultimate");
   207→
   208→  const shopifyPlan = isAnnual
   209→    ? plan.shopifyPlanAnnual
   210→    : plan.shopifyPlanMonthly;
   211→
   212→  const displayPrice = isAnnual
   213→    ? plan.annualMonthlyPrice
   214→    : plan.monthlyPrice;
   215→
   216→  let buttonContent = "Start 14-day free trial";
   217→  if (isCurrent) {
   218→    buttonContent = "Current plan";
   219→  } else if (plan.id === "free" && isCurrentPaid) {
   220→    buttonContent = "Downgrade to Free";
   221→  } else if (isDowngrade) {
   222→    buttonContent = `Downgrade to ${plan.name}`;
   223→  } else if (currentTier !== "free") {
   224→    buttonContent = `Switch to ${plan.name}`;
   225→  }
   226→
   227→  const handleClick = () => {
   228→    if (isCurrent) return;
   229→    if (plan.id === "free" || isDowngrade) {
   230→      onRequestCancel();
   231→    } else if (shopifyPlan) {
   232→      onSubscribe(shopifyPlan);
   233→    }
   234→  };
   235→
   236→  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");
   237→
   238→  const cardInner = (
   239→    <Card>
   240→      <BlockStack gap="400">
   241→        {/* Header */}
   242→        <BlockStack gap="100">
   243→          <InlineStack align="space-between" blockAlign="center">
   244→            <Text as="h3" variant="headingMd" fontWeight="bold">
   245→              {plan.name}
   246→            </Text>
   247→            <InlineStack gap="200">
   248→              {isBestValue && <Badge tone="info">Most popular</Badge>}
   249→              {isCurrent && <Badge tone="success">Current</Badge>}
   250→            </InlineStack>
   251→          </InlineStack>
   252→          <Text as="p" variant="bodySm" tone="subdued">
   253→            {plan.description}
   254→          </Text>
   255→        </BlockStack>
   256→
   257→        <Divider />
   258→
   259→        {/* Price */}
   260→        <BlockStack gap="050">
   261→          {plan.monthlyPrice === 0 ? (
   262→            <Text as="p" variant="headingXl" fontWeight="bold">
   263→              Free
   264→            </Text>
   265→          ) : (
   266→            <>
   267→              <InlineStack gap="100" blockAlign="baseline">
   268→                <Text as="p" variant="headingXl" fontWeight="bold">
   269→                  ${displayPrice}
   270→                </Text>
   271→                <Text as="p" variant="bodySm" tone="subdued">
   272→                  / month
   273→                </Text>
   274→              </InlineStack>
   275→              {isAnnual && (
   276→                <Text as="p" variant="bodySm" tone="subdued">
   277→                  billed ${plan.annualPrice} / year
   278→                </Text>
   279→              )}
   280→              {!isAnnual && (
   281→                <Text as="p" variant="bodySm" tone="subdued">
   282→                  or ${plan.annualMonthlyPrice}/mo billed annually
   283→                </Text>
   284→              )}
   285→            </>
   286→          )}
   287→        </BlockStack>
   288→
   289→        {/* CTA */}
   290→        <Button
   291→          variant={isCurrent ? "secondary" : "primary"}
   292→          tone={
   293→            plan.id === "free" && isCurrentPaid ? "critical" : undefined
   294→          }
   295→          onClick={handleClick}
   296→          disabled={isCurrent}
   297→          loading={isThisLoading}
   298→          fullWidth
   299→        >
   300→          {buttonContent}
   301→        </Button>
   302→
   303→        <Divider />
   304→
   305→        {/* Features */}
   306→        <BlockStack gap="300">
   307→          {plan.features.map((f) => (
   308→            <PlanFeature key={f} feature={f} />
   309→          ))}
   310→        </BlockStack>
   311→      </BlockStack>
   312→    </Card>
   313→  );
   314→
   315→  // Highlight the current plan with an emphasis border
   316→  if (isCurrent) {
   317→    return (
   318→      <Box
   319→        borderWidth="050"
   320→        borderColor="border-emphasis"
   321→        borderRadius="300"
   322→      >
   323→        {cardInner}
   324→      </Box>
   325→    );
   326→  }
   327→
   328→  return cardInner;
   329→}
   330→
   331→// ─── Page component ───────────────────────────────────────────────────────────
   332→
   333→export default function PricingPage() {
   334→  const { subscription } = useLoaderData<typeof loader>();
   335→  const fetcher = useFetcher<typeof action>();
   336→  const shopify = useAppBridge();
   337→
   338→  const [isAnnual, setIsAnnual] = useState(
   339→    subscription.billingInterval === "annual",
   340→  );
   341→  const [loadingPlan, setLoadingPlan] = useState<string | null>(null);
   342→  const [cancelModalOpen, setCancelModalOpen] = useState(false);
   343→
   344→  const data = fetcher.data;
   345→  const isFetching = fetcher.state !== "idle";
   346→
   347→  // Redirect to Shopify billing confirmation page
   348→  useEffect(() => {
   349→    if (data && "confirmationUrl" in data && data.confirmationUrl) {
   350→      window.open(data.confirmationUrl as string, "_top");
   351→    }
   352→  }, [data]);
   353→
   354→  // Toast on success/error + clear loading
   355→  useEffect(() => {
   356→    if (!isFetching) {
   357→      setLoadingPlan(null);
   358→    }
   359→    if (data && "message" in data && data.message) {
   360→      shopify.toast.show(data.message as string);
   361→    }
   362→    if (data && "error" in data && data.error) {
   363→      shopify.toast.show(data.error as string, { isError: true });
   364→    }
   365→  }, [data, isFetching, shopify]);
   366→
   367→  const handleSubscribe = useCallback(
   368→    (planName: string) => {
   369→      setLoadingPlan(planName);
   370→      const fd = new FormData();
   371→      fd.set("intent", "subscribe");
   372→      fd.set("plan", planName);
   373→      fetcher.submit(fd, { method: "POST" });
   374→    },
   375→    [fetcher],
   376→  );
   377→
   378→  const handleConfirmCancel = useCallback(() => {
   379→    setCancelModalOpen(false);
   380→    setLoadingPlan("cancel");
   381→    const fd = new FormData();
   382→    fd.set("intent", "cancel");
   383→    fetcher.submit(fd, { method: "POST" });
   384→  }, [fetcher]);
   385→
   386→  const currentTier = subscription.planTier;
   387→
   388→  const planBadgeTone =
   389→    currentTier === "ultimate"
   390→      ? "attention"
   391→      : currentTier === "pro"
   392→        ? "info"
   393→        : "new";
   394→
   395→  return (
   396→    <Page
   397→      title="Pricing"
   398→      subtitle="Choose the plan that's right for your store"
   399→      backAction={{ url: "/app" }}
   400→    >
   401→      <Layout>
   402→        <Layout.Section>
   403→          <BlockStack gap="600">
   404→
   405→            {/* Current plan status card */}
   406→            {currentTier === "free" ? (
   407→              <Card>
   408→                <InlineStack align="space-between" blockAlign="center" wrap>
   409→                  <InlineStack gap="300" blockAlign="center">
   410→                    <Box
   411→                      background="bg-surface-secondary"
   412→                      borderRadius="200"
   413→                      padding="300"
   414→                    >
   415→                      <Text as="p" variant="headingLg">🆓</Text>
   416→                    </Box>
   417→                    <BlockStack gap="050">
   418→                      <InlineStack gap="200" blockAlign="center">
   419→                        <Text as="p" variant="headingSm" fontWeight="bold">
   420→                          Free Plan
   421→                        </Text>
   422→                        <Badge tone="new">Active</Badge>
   423→                      </InlineStack>
   424→                      <Text as="p" variant="bodySm" tone="subdued">
   425→                        Up to 25 zip codes · Allowed zip codes only · Basic widget
   426→                      </Text>
   427→                    </BlockStack>
   428→                  </InlineStack>
   429→                  <Button variant="primary" onClick={() => setCancelModalOpen(false)}>
   430→                    Upgrade now ↓
   431→                  </Button>
   432→                </InlineStack>
   433→              </Card>
   434→            ) : (
   435→              <Banner
   436→                tone="success"
   437→                title={`You're on the ${PLANS_DATA[currentTier as keyof typeof PLANS_DATA]?.name ?? ""} plan`}
   438→              >
   439→                <InlineStack gap="200" blockAlign="center">
   440→                  <Badge tone="success">Active</Badge>
   441→                  <Text as="p" variant="bodySm">
   442→                    {currentTier === "ultimate"
   443→                      ? "You have access to all features including VIP support and API access."
   444→                      : "You have unlimited zip codes, blocked areas, delivery rules, and more."}
   445→                  </Text>
   446→                </InlineStack>
   447→              </Banner>
   448→            )}
   449→
   450→            {/* Error / success feedback banners */}
   451→            {data && "error" in data && data.error && (
   452→              <Banner tone="critical">{String(data.error)}</Banner>
   453→            )}
   454→            {data && "success" in data && data.success && (
   455→              <Banner tone="success">
   456→                {data && "message" in data ? String(data.message) : "Plan updated."}
   457→              </Banner>
   458→            )}
   459→
   460→            {/* Centered billing toggle */}
   461→            <BlockStack gap="200" inlineAlign="center">
   462→              <Text as="p" variant="bodySm" tone="subdued" alignment="center">
   463→                Billing period
   464→              </Text>
   465→              <InlineStack gap="0" blockAlign="center">
   466→                <div
   467→                  style={{
   468→                    display: "flex",
   469→                    background: "var(--p-color-bg-surface-secondary, #f6f6f7)",
   470→                    borderRadius: "var(--p-border-radius-200, 8px)",
   471→                    padding: "4px",
   472→                    gap: "4px",
   473→                  }}
   474→                >
   475→                  <button
   476→                    onClick={() => setIsAnnual(false)}
   477→                    style={{
   478→                      padding: "8px 20px",
   479→                      borderRadius: "6px",
   480→                      border: "none",
   481→                      cursor: "pointer",
   482→                      fontWeight: 600,
   483→                      fontSize: "14px",
   484→                      fontFamily: "inherit",
   485→                      background: !isAnnual
   486→                        ? "var(--p-color-bg-surface, #fff)"
   487→                        : "transparent",
   488→                      boxShadow: !isAnnual
   489→                        ? "0 1px 3px rgba(0,0,0,0.12), 0 1px 2px rgba(0,0,0,0.06)"
   490→                        : "none",
   491→                      color: !isAnnual
   492→                        ? "var(--p-color-text, #1a1a1a)"
   493→                        : "var(--p-color-text-subdued, #6d7175)",
   494→                      transition: "all 0.15s ease",
   495→                    }}
   496→                  >
   497→                    Monthly
   498→                  </button>
   499→                  <button
   500→                    onClick={() => setIsAnnual(true)}
   501→                    style={{
   502→                      padding: "8px 20px",
   503→                      borderRadius: "6px",
   504→                      border: "none",
   505→                      cursor: "pointer",
   506→                      fontWeight: 600,
   507→                      fontSize: "14px",
   508→                      fontFamily: "inherit",
   509→                      background: isAnnual
   510→                        ? "var(--p-color-bg-surface, #fff)"
   511→                        : "transparent",
   512→                      boxShadow: isAnnual
   513→                        ? "0 1px 3px rgba(0,0,0,0.12), 0 1px 2px rgba(0,0,0,0.06)"
   514→                        : "none",
   515→                      color: isAnnual
   516→                        ? "var(--p-color-text, #1a1a1a)"
   517→                        : "var(--p-color-text-subdued, #6d7175)",
   518→                      transition: "all 0.15s ease",
   519→                      display: "flex",
   520→                      alignItems: "center",
   521→                      gap: "8px",
   522→                    }}
   523→                  >
   524→                    Annual
   525→                    <span
   526→                      style={{
   527→                        background: "#d4f0e0",
   528→                        color: "#1a6b3c",
   529→                        fontSize: "11px",
   530→                        fontWeight: 700,
   531→                        padding: "2px 7px",
   532→                        borderRadius: "20px",
   533→                        letterSpacing: "0.02em",
   534→                      }}
   535→                    >
   536→                      Save 20%
   537→                    </span>
   538→                  </button>
   539→                </div>
   540→              </InlineStack>
   541→            </BlockStack>
   542→
   543→            {/* Plan cards — centered grid */}
   544→            <Box maxWidth="960px" width="100%">
   545→              <div style={{ margin: "0 auto" }}>
   546→                <InlineGrid columns={{ xs: 1, sm: 1, md: 3 }} gap="400">
   547→                  {(
   548→                    Object.values(PLANS_DATA) as (typeof PLANS_DATA)[keyof typeof PLANS_DATA][]
   549→                  ).map((plan) => (
   550→                    <PlanCard
