   552→                      plan={plan}
   553→                      isAnnual={isAnnual}
   554→                      currentTier={currentTier}
   555→                      onSubscribe={handleSubscribe}
   556→                      onRequestCancel={() => setCancelModalOpen(true)}
   557→                      loadingPlan={loadingPlan}
   558→                    />
   559→                  ))}
   560→                </InlineGrid>
   561→              </div>
   562→            </Box>
   563→
   564→            {/* Trial note */}
   565→            {currentTier === "free" && (
   566→              <Text as="p" variant="bodySm" tone="subdued" alignment="center">
   567→                All paid plans include a 14-day free trial. No credit card charged until the trial ends.
   568→              </Text>
   569→            )}
   570→
   571→          </BlockStack>
   572→        </Layout.Section>
   573→      </Layout>
   574→
   575→      {/* Downgrade confirmation modal */}
   576→      <Modal
   577→        open={cancelModalOpen}
   578→        onClose={() => setCancelModalOpen(false)}
   579→        title="Downgrade to Free plan?"
   580→        primaryAction={{
   581→          content: "Downgrade",
   582→          destructive: true,
   583→          onAction: handleConfirmCancel,
   584→          loading: loadingPlan === "cancel",
   585→        }}
   586→        secondaryActions={[
   587→          {
   588→            content: "Keep current plan",
   589→            onAction: () => setCancelModalOpen(false),
   590→          },
   591→        ]}
   592→      >
   593→        <Modal.Section>
   594→          <BlockStack gap="300">
   595→            <Text as="p" variant="bodyMd">
   596→              You will immediately lose access to paid features including:
   597→            </Text>
   598→            <BlockStack gap="200">
   599→              <Text as="p" variant="bodyMd">· Unlimited zip codes (limited to 25)</Text>
   600→              <Text as="p" variant="bodyMd">· Blocked zip codes</Text>
   601→              <Text as="p" variant="bodyMd">· Delivery zones, ETAs, and rules</Text>
   602→              <Text as="p" variant="bodyMd">· Customer waitlist</Text>
   603→            </BlockStack>
   604→            <Text as="p" variant="bodyMd" tone="subdued">
   605→              Any zip codes over the 25-entry limit will remain saved but become inactive.
   606→            </Text>
   607→          </BlockStack>
   608→        </Modal.Section>
   609→      </Modal>
   610→    </Page>
   611→  );
   612→}
   613→
   614→export const headers: HeadersFunction = (headersArgs) => {
   615→  return boundary.headers(headersArgs);
   616→};
