import { useState, useEffect, useCallback } from "react";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import { useFetcher, useLoaderData } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { boundary } from "@shopify/shopify-app-react-router/server";
import { authenticate } from "../shopify.server";
import {
  ALL_PAID_PLANS,
  PLAN_PRO_MONTHLY,
  PLAN_PRO_ANNUAL,
  PLAN_ULTIMATE_MONTHLY,
  PLAN_ULTIMATE_ANNUAL,
} from "../plans";
import {
  syncSubscriptionFromShopify,
  cancelShopSubscription,
  getShopSubscription,
} from "../billing.server";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  ButtonGroup,
  Divider,
  Box,
  Banner,
  Icon,
  Modal,
  InlineGrid,
} from "@shopify/polaris";
import { CheckCircleIcon, StarIcon } from "@shopify/polaris-icons";

// ─── Plan data ────────────────────────────────────────────────────────────────

const PLANS_DATA = {
  free: {
    id: "free",
    name: "Free",
    monthlyPrice: 0,
    annualPrice: 0,
    annualMonthlyPrice: 0,
    description: "Perfect for new stores getting started",
    features: [
      "Up to 25 zip codes",
      "Allowed zip codes only",
      "Basic storefront widget",
      "Standard email support",
    ],
    shopifyPlanMonthly: null as string | null,
    shopifyPlanAnnual: null as string | null,
  },
  pro: {
    id: "pro",
    name: "Pro",
    monthlyPrice: 12.99,
    annualPrice: 99,
    annualMonthlyPrice: 8.25,
    description: "For growing stores that need more control",
    features: [
      "Unlimited zip codes",
      "Allowed + Blocked zip codes",
      "Delivery zones & ETAs",
      "Bulk CSV import & export",
      "Customer waitlist",
      "Priority email support",
    ],
    shopifyPlanMonthly: PLAN_PRO_MONTHLY,
    shopifyPlanAnnual: PLAN_PRO_ANNUAL,
    bestValue: true,
  },
  ultimate: {
    id: "ultimate",
    name: "Ultimate",
    monthlyPrice: 24.99,
    annualPrice: 199,
    annualMonthlyPrice: 16.58,
    description: "For high-volume stores needing top-tier features",
    features: [
      "Everything in Pro",
      "Advanced delivery rules",
      "Customisable widget CSS",
      "API access",
      "24/7 VIP support",
      "Early access to new features",
    ],
    shopifyPlanMonthly: PLAN_ULTIMATE_MONTHLY,
    shopifyPlanAnnual: PLAN_ULTIMATE_ANNUAL,
  },
};

// ─── Loader ───────────────────────────────────────────────────────────────────

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session, billing } = await authenticate.admin(request);
  const shop = session.shop;

  try {
    const billingCheck = await billing.check({
      plans: ALL_PAID_PLANS,
      isTest: process.env.NODE_ENV !== "production",
    });
    const subscription = await syncSubscriptionFromShopify(
      shop,
      billingCheck.appSubscriptions ?? [],
    );
    return { subscription };
  } catch {
    const subscription = await getShopSubscription(shop);
    return { subscription };
  }
};

// ─── Action ───────────────────────────────────────────────────────────────────

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session, billing } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = String(formData.get("intent"));

  if (intent === "subscribe") {
    const plan = String(formData.get("plan"));
    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;
    try {
      const confirmationUrl = await billing.request({
        plan,
        isTest: process.env.NODE_ENV !== "production",
        returnUrl,
      });
      return { confirmationUrl };
    } catch {
      return { error: "Failed to initiate subscription. Please try again." };
    }
  }

  if (intent === "cancel") {
    try {
      const sub = await getShopSubscription(shop);
      if (sub.shopifySubscriptionId) {
        await billing.cancel({
          subscriptionId: sub.shopifySubscriptionId,
          isTest: process.env.NODE_ENV !== "production",
          prorate: true,
        });
      }
      await cancelShopSubscription(shop);
      return {
        success: true,
        message: "Subscription cancelled. You are now on the Free plan.",
      };
    } catch {
      return { error: "Failed to cancel subscription. Please try again." };
    }
  }

  return null;
};

// ─── Feature row ─────────────────────────────────────────────────────────────

function PlanFeature({ feature }: { feature: string }) {
  return (
    <InlineStack gap="200" blockAlign="start" wrap={false}>
      <Box>
        <Icon source={CheckCircleIcon} tone="success" />
      </Box>
      <Text as="span" variant="bodyMd">
        {feature}
      </Text>
    </InlineStack>
  );
}

// ─── Plan card ────────────────────────────────────────────────────────────────

type PlanCardProps = {
  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
  isAnnual: boolean;
  currentTier: string;
  onSubscribe: (planName: string) => void;
  onRequestCancel: () => void;
  loadingPlan: string | null;
};

function PlanCard({
  plan,
  isAnnual,
  currentTier,
  onSubscribe,
  onRequestCancel,
  loadingPlan,
}: PlanCardProps) {
  const isCurrent = currentTier === plan.id;
  const isBestValue = "bestValue" in plan && plan.bestValue;
  const isCurrentPaid = currentTier !== "free";
  const isDowngrade =
    (plan.id === "free" && isCurrentPaid) ||
    (plan.id === "pro" && currentTier === "ultimate");

  const shopifyPlan = isAnnual
    ? plan.shopifyPlanAnnual
    : plan.shopifyPlanMonthly;

  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;

  let buttonContent = "Start 14-day free trial";
  if (isCurrent) {
    buttonContent = "Current plan";
  } else if (plan.id === "free" && isCurrentPaid) {
    buttonContent = "Downgrade to Free";
  } else if (isDowngrade) {
    buttonContent = `Downgrade to ${plan.name}`;
  } else if (currentTier !== "free") {
    buttonContent = `Switch to ${plan.name}`;
  }

  const handleClick = () => {
    if (isCurrent) return;
    if (plan.id === "free" || isDowngrade) {
      onRequestCancel();
    } else if (shopifyPlan) {
      onSubscribe(shopifyPlan);
    }
  };

  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");

  const cardContent = (
    <Card>
      <BlockStack gap="400">

        {/* Plan name + badges */}
        <BlockStack gap="100">
          <InlineStack align="space-between" blockAlign="center">
            <Text as="h3" variant="headingMd" fontWeight="bold">
              {plan.name}
            </Text>
            <InlineStack gap="150">
              {isBestValue && (
                <Badge tone="info" icon={StarIcon}>
                  Most popular
                </Badge>
              )}
              {isCurrent && <Badge tone="success">Current</Badge>}
            </InlineStack>
          </InlineStack>
          <Text as="p" variant="bodySm" tone="subdued">
            {plan.description}
          </Text>
        </BlockStack>

        <Divider />

        {/* Price */}
        <BlockStack gap="100">
          {plan.monthlyPrice === 0 ? (
            <>
              <Text as="p" variant="headingXl" fontWeight="bold">
                Free
              </Text>
              <Text as="p" variant="bodySm" tone="subdued">
                forever
              </Text>
            </>
          ) : (
            <>
              <InlineStack gap="100" blockAlign="baseline">
                <Text as="p" variant="headingXl" fontWeight="bold">
                  ${displayPrice}
                </Text>
                <Text as="p" variant="bodySm" tone="subdued">
                  / month
                </Text>
              </InlineStack>
              <Text as="p" variant="bodySm" tone="subdued">
                {isAnnual
                  ? `billed $${plan.annualPrice} / year`
                  : `or $${plan.annualMonthlyPrice}/mo billed annually`}
              </Text>
            </>
          )}
        </BlockStack>

        {/* CTA button */}
        <Button
          variant={isCurrent ? "secondary" : "primary"}
          tone={plan.id === "free" && isCurrentPaid ? "critical" : undefined}
          onClick={handleClick}
          disabled={isCurrent}
          loading={isThisLoading}
          fullWidth
        >
          {buttonContent}
        </Button>

        <Divider />

        {/* Features list */}
        <BlockStack gap="300">
          {plan.features.map((f) => (
            <PlanFeature key={f} feature={f} />
          ))}
        </BlockStack>

      </BlockStack>
    </Card>
  );

  // Emphasise the current plan card with a border
  if (isCurrent) {
    return (
      <Box borderWidth="050" borderColor="border-emphasis" borderRadius="300">
        {cardContent}
      </Box>
    );
  }

  return cardContent;
}

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function PricingPage() {
  const { subscription } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  const [isAnnual, setIsAnnual] = useState(
    subscription.billingInterval === "annual",
  );
  const [loadingPlan, setLoadingPlan] = useState<string | null>(null);
  const [cancelModalOpen, setCancelModalOpen] = useState(false);

  const data = fetcher.data;
  const isFetching = fetcher.state !== "idle";

  // Redirect to Shopify billing confirmation page
  useEffect(() => {
    if (data && "confirmationUrl" in data && data.confirmationUrl) {
      window.open(data.confirmationUrl as string, "_top");
    }
  }, [data]);

  // Toast notifications + clear loading state
  useEffect(() => {
    if (!isFetching) setLoadingPlan(null);
    if (data && "message" in data && data.message) {
      shopify.toast.show(data.message as string);
    }
    if (data && "error" in data && data.error) {
      shopify.toast.show(data.error as string, { isError: true });
    }
  }, [data, isFetching, shopify]);

  const handleSubscribe = useCallback(
    (planName: string) => {
      setLoadingPlan(planName);
      const fd = new FormData();
      fd.set("intent", "subscribe");
      fd.set("plan", planName);
      fetcher.submit(fd, { method: "POST" });
    },
    [fetcher],
  );

  const handleConfirmCancel = useCallback(() => {
    setCancelModalOpen(false);
    setLoadingPlan("cancel");
    const fd = new FormData();
    fd.set("intent", "cancel");
    fetcher.submit(fd, { method: "POST" });
  }, [fetcher]);

  const currentTier = subscription.planTier;
  const currentPlanName =
    PLANS_DATA[currentTier as keyof typeof PLANS_DATA]?.name ?? "Free";

  const planBadgeTone =
    currentTier === "ultimate"
      ? "attention"
      : currentTier === "pro"
        ? "info"
        : "new";

  return (
    <Page
      title="Pricing"
      subtitle="Choose the plan that's right for your store"
      backAction={{ url: "/app" }}
    >
      <Layout>
        <Layout.Section>
          <BlockStack gap="600">

            {/* Current plan status */}
            {currentTier === "free" ? (
              <Banner
                tone="info"
                title="You're on the Free plan"
                action={{
                  content: "Upgrade to Pro",
                  onAction: () => {
                    const plan = isAnnual
                      ? PLANS_DATA.pro.shopifyPlanAnnual
                      : PLANS_DATA.pro.shopifyPlanMonthly;
                    if (plan) handleSubscribe(plan);
                  },
                }}
              >
                <Text as="p" variant="bodyMd">
                  You have up to 25 allowed zip codes and basic widget access.
                  Upgrade to unlock unlimited zip codes, blocked areas, delivery
                  rules, and more.
                </Text>
              </Banner>
            ) : (
              <Banner tone="success" title={`You're on the ${currentPlanName} plan`}>
                <InlineStack gap="200" blockAlign="center">
                  <Badge tone="success">Active</Badge>
                  <Text as="p" variant="bodyMd">
                    {currentTier === "ultimate"
                      ? "You have full access to all features including VIP support and API access."
                      : "You have unlimited zip codes, blocked areas, delivery rules, and more."}
                  </Text>
                </InlineStack>
              </Banner>
            )}

            {/* Action feedback banners */}
            {data && "error" in data && data.error && (
              <Banner tone="critical">{String(data.error)}</Banner>
            )}
            {data && "success" in data && data.success && (
              <Banner tone="success">
                {data && "message" in data
                  ? String(data.message)
                  : "Plan updated successfully."}
              </Banner>
            )}

            {/* Billing toggle — centred, fully Polaris */}
            <BlockStack gap="200" inlineAlign="center">
              <Text as="p" variant="bodySm" tone="subdued" alignment="center">
                Billing period
              </Text>
              <ButtonGroup variant="segmented">
                <Button
                  pressed={!isAnnual}
                  onClick={() => setIsAnnual(false)}
                >
                  Monthly
                </Button>
                <Button
                  pressed={isAnnual}
                  onClick={() => setIsAnnual(true)}
                >
                  Annual · Save 20%
                </Button>
              </ButtonGroup>
              {isAnnual && (
                <Badge tone="success">You save up to 36% per year</Badge>
              )}
            </BlockStack>

            {/* Plan cards */}
            <InlineGrid columns={{ xs: 1, sm: 1, md: 3 }} gap="400">
              {(
                Object.values(
                  PLANS_DATA,
                ) as (typeof PLANS_DATA)[keyof typeof PLANS_DATA][]
              ).map((plan) => (
                <PlanCard
                  key={plan.id}
                  plan={plan}
                  isAnnual={isAnnual}
                  currentTier={currentTier}
                  onSubscribe={handleSubscribe}
                  onRequestCancel={() => setCancelModalOpen(true)}
                  loadingPlan={loadingPlan}
                />
              ))}
            </InlineGrid>

            {/* Trial footnote */}
            {currentTier === "free" && (
              <Text
                as="p"
                variant="bodySm"
                tone="subdued"
                alignment="center"
              >
                All paid plans include a 14-day free trial. No credit card
                charged until the trial ends.
              </Text>
            )}

            {/* Current plan footer badge */}
            <BlockStack inlineAlign="center" gap="100">
              <InlineStack gap="200" blockAlign="center">
                <Text as="p" variant="bodySm" tone="subdued">
                  Your current plan:
                </Text>
                <Badge tone={planBadgeTone}>{currentPlanName}</Badge>
              </InlineStack>
            </BlockStack>

          </BlockStack>
        </Layout.Section>
      </Layout>

      {/* Downgrade confirmation modal */}
      <Modal
        open={cancelModalOpen}
        onClose={() => setCancelModalOpen(false)}
        title="Downgrade to Free plan?"
        primaryAction={{
          content: "Yes, downgrade",
          destructive: true,
          onAction: handleConfirmCancel,
          loading: loadingPlan === "cancel",
        }}
        secondaryActions={[
          {
            content: "Keep current plan",
            onAction: () => setCancelModalOpen(false),
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="300">
            <Text as="p" variant="bodyMd">
              You will immediately lose access to:
            </Text>
            <BlockStack gap="200">
              <InlineStack gap="200" blockAlign="center">
                <Icon source={CheckCircleIcon} tone="critical" />
                <Text as="p" variant="bodyMd">Unlimited zip codes (limited to 25)</Text>
              </InlineStack>
              <InlineStack gap="200" blockAlign="center">
                <Icon source={CheckCircleIcon} tone="critical" />
                <Text as="p" variant="bodyMd">Blocked zip codes</Text>
              </InlineStack>
              <InlineStack gap="200" blockAlign="center">
                <Icon source={CheckCircleIcon} tone="critical" />
                <Text as="p" variant="bodyMd">Delivery zones, ETAs, and rules</Text>
              </InlineStack>
              <InlineStack gap="200" blockAlign="center">
                <Icon source={CheckCircleIcon} tone="critical" />
                <Text as="p" variant="bodyMd">Customer waitlist</Text>
              </InlineStack>
            </BlockStack>
            <Banner tone="warning">
              <Text as="p" variant="bodyMd">
                Zip codes over the 25-entry limit will remain saved but become inactive.
              </Text>
            </Banner>
          </BlockStack>
        </Modal.Section>
      </Modal>
    </Page>
  );
}

