  } else if (!isCurrent && plan.id !== "free" && isCurrentPaid) {
    // Paid → lower paid (e.g. Ultimate → Pro)
    buttonContent = `Switch to ${plan.name}`;
  }

  const handleClick = () => {
    if (isCurrent) return;
    if (isDowngradeToFree) {
      // Only cancellation flow (loses all paid features → needs confirmation)
      onRequestCancel();
    } else if (shopifyPlan) {
      // All paid plan changes (upgrade or paid-to-paid switch) go via billing.request
      onSubscribe(shopifyPlan);
    }
  };

  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");

  return (
    <Card>
