import { useState, useCallback, useMemo } from "react";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import { useFetcher, useLoaderData, useNavigate } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";
import { getShopSubscription } from "../billing.server";
import { PLAN_LIMITS } from "../plans";
import {
  Page,
  Layout,
  Card,
  TextField,
  Button,
  Banner,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  DataTable,
  Modal,
  Select,
  Divider,
  EmptyState,
  Box,
  Icon,
  Tooltip,
  CalloutCard,
  DropZone,
  Spinner,
  Pagination,
} from "@shopify/polaris";
import {
  SearchIcon,
  DeleteIcon,
  PlusIcon,
  StarIcon,
  ImportIcon,
  ExportIcon,
} from "@shopify/polaris-icons";

const PAGE_SIZE = 10;

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const [zipCodes, subscription] = await Promise.all([
    db.zipCode.findMany({
      where: { shop },
      orderBy: { createdAt: "desc" },
    }),
    getShopSubscription(shop),
  ]);

  const stats = {
    total: zipCodes.length,
    allowed: zipCodes.filter((z) => z.type === "allowed").length,
    blocked: zipCodes.filter((z) => z.type === "blocked").length,
    active: zipCodes.filter((z) => z.isActive).length,
  };

  return { zipCodes, stats, subscription };
};

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent");

  if (intent === "add") {
    const zipCode = String(formData.get("zipCode")).trim().toUpperCase();
    const label = String(formData.get("label") || "").trim();
    const zone = String(formData.get("zone") || "").trim();
    const message = String(formData.get("message") || "").trim();
    const eta = String(formData.get("eta") || "").trim();
    const type = String(formData.get("type") || "allowed");

    if (!zipCode) return { error: "Zip code is required." };

    const subscription = await getShopSubscription(shop);
    const limits = PLAN_LIMITS[subscription.planTier];

    if (type === "blocked" && !limits.allowBlocked) {
      return {
        error:
          "Blocked zip codes are not available on the Free plan. Upgrade to Pro or Ultimate.",
        upgradeRequired: true,
      };
    }

    const currentCount = await db.zipCode.count({ where: { shop } });
    if (limits.maxZipCodes !== Infinity && currentCount >= limits.maxZipCodes) {
      return {
        error: `You have reached the ${limits.maxZipCodes} zip code limit for the Free plan. Upgrade to Pro for unlimited zip codes.`,
        upgradeRequired: true,
      };
    }

    try {
      await db.zipCode.create({
        data: {
          shop,
          zipCode,
          label: label || null,
          zone: zone || null,
          message: message || null,
          eta: eta || null,
          type,
        },
      });
      return { success: true, action: "added", zipCode };
    } catch {
      return { error: `Zip code "${zipCode}" already exists.` };
    }
  }

  if (intent === "delete") {
    const id = String(formData.get("id"));
    await db.zipCode.delete({ where: { id } });
    return { success: true, action: "deleted" };
  }

  if (intent === "toggle") {
    const id = String(formData.get("id"));
    const isActive = formData.get("isActive") === "true";
    await db.zipCode.update({
      where: { id },
      data: { isActive: !isActive },
    });
    return { success: true, action: "toggled" };
  }

  if (intent === "check") {
    const zipCode = String(formData.get("checkZip")).trim().toUpperCase();
    const found = await db.zipCode.findUnique({
      where: { shop_zipCode: { shop, zipCode } },
    });
    if (!found) return { checkResult: { found: false, zipCode } };
    return { checkResult: { found: true, zipCode, record: found } };
  }

  if (intent === "bulk-import") {
    const csvData = String(formData.get("csvData") || "");
    if (!csvData.trim()) return { error: "No CSV data provided." };

    const subscription = await getShopSubscription(shop);
    const limits = PLAN_LIMITS[subscription.planTier];

    const lines = csvData
      .split("\n")
      .map((l) => l.trim())
      .filter((l) => l.length > 0);

    // Skip header row if present
    const startIdx =
      lines.length > 0 &&
      lines[0].toLowerCase().includes("zip")
        ? 1
        : 0;

    const currentCount = await db.zipCode.count({ where: { shop } });
    let imported = 0;
    let skipped = 0;
    const errors: string[] = [];

    for (let i = startIdx; i < lines.length; i++) {
      const cols = lines[i].split(",").map((c) => c.trim().replace(/^"|"$/g, ""));
      const zipCode = (cols[0] || "").toUpperCase();
      if (!zipCode) continue;

      const zone = cols[1] || null;
      const type = (cols[2] || "allowed").toLowerCase() === "blocked" ? "blocked" : "allowed";
      const message = cols[3] || null;
      const eta = cols[4] || null;

      if (type === "blocked" && !limits.allowBlocked) {
        skipped++;
        continue;
      }

      if (
        limits.maxZipCodes !== Infinity &&
        currentCount + imported >= limits.maxZipCodes
      ) {
        errors.push(
          `Reached the ${limits.maxZipCodes} zip code limit. ${lines.length - startIdx - imported - skipped} zip codes were not imported.`,
        );
        break;
      }

      try {
        await db.zipCode.upsert({
          where: { shop_zipCode: { shop, zipCode } },
          create: {
            shop,
            zipCode,
            zone,
            type,
            message,
            eta,
          },
          update: {
            zone: zone ?? undefined,
            type,
            message: message ?? undefined,
            eta: eta ?? undefined,
          },
        });
        imported++;
      } catch {
        skipped++;
      }
    }

    return {
      success: true,
      action: "bulk-import",
      imported,
      skipped,
      errors,
    };
  }

  if (intent === "export") {
    const zipCodes = await db.zipCode.findMany({
      where: { shop },
      orderBy: { createdAt: "desc" },
    });

    const header = "Zip Code,Zone,Status,Message,ETA,Active";
    const rows = zipCodes.map(
      (z) =>
        `"${z.zipCode}","${z.zone || ""}","${z.type}","${z.message || ""}","${z.eta || ""}","${z.isActive ? "Yes" : "No"}"`,
    );
    const csv = [header, ...rows].join("\n");

    return { success: true, action: "export", csv };
  }

  return null;
};

type ZipCodeRecord = {
  id: string;
  zipCode: string;
  label: string | null;
  zone: string | null;
  message: string | null;
  eta: string | null;
  type: string;
  isActive: boolean;
  createdAt: string | Date;
};

export default function ZipCodeCheckerPage() {
  const { zipCodes, stats, subscription } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();
  const navigate = useNavigate();

  const limits = PLAN_LIMITS[subscription.planTier];
  const isFreePlan = subscription.planTier === "free";
  const atZipLimit =
    limits.maxZipCodes !== Infinity && stats.total >= limits.maxZipCodes;

  // Search & filter state
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [currentPage, setCurrentPage] = useState(1);

  // Check zip code state
  const [checkZip, setCheckZip] = useState("");

  // Add modal state
  const [addModalOpen, setAddModalOpen] = useState(false);
  const [newZip, setNewZip] = useState("");
  const [newLabel, setNewLabel] = useState("");
  const [newZone, setNewZone] = useState("");
  const [newMessage, setNewMessage] = useState("");
  const [newEta, setNewEta] = useState("");
  const [newType, setNewType] = useState("allowed");

  // Import modal state
  const [importModalOpen, setImportModalOpen] = useState(false);
  const [csvText, setCsvText] = useState("");
  const [importFile, setImportFile] = useState<File | null>(null);

  const isCheckLoading =
    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "check";
  const isAddLoading =
    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "add";
  const isImportLoading =
    fetcher.state !== "idle" &&
    fetcher.formData?.get("intent") === "bulk-import";

  const checkResult =
    fetcher.data && "checkResult" in fetcher.data
      ? fetcher.data.checkResult
      : null;
  const actionError =
    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
  const upgradeRequired =
    fetcher.data && "upgradeRequired" in fetcher.data
      ? fetcher.data.upgradeRequired
      : false;
  const importResult =
    fetcher.data &&
    "action" in fetcher.data &&
    fetcher.data.action === "bulk-import"
      ? fetcher.data
      : null;

  // Filtered zip codes
  const filteredZipCodes = useMemo(() => {
    let filtered = zipCodes as ZipCodeRecord[];

    if (searchQuery.trim()) {
      const q = searchQuery.trim().toLowerCase();
      filtered = filtered.filter(
        (z) =>
          z.zipCode.toLowerCase().includes(q) ||
          (z.zone && z.zone.toLowerCase().includes(q)) ||
          (z.label && z.label.toLowerCase().includes(q)) ||
          (z.message && z.message.toLowerCase().includes(q)),
      );
    }

    if (statusFilter === "allowed") {
      filtered = filtered.filter((z) => z.type === "allowed");
    } else if (statusFilter === "blocked") {
      filtered = filtered.filter((z) => z.type === "blocked");
    }

    return filtered;
  }, [zipCodes, searchQuery, statusFilter]);

  // Pagination
  const totalPages = Math.max(1, Math.ceil(filteredZipCodes.length / PAGE_SIZE));
  const paginatedZipCodes = useMemo(() => {
    const start = (currentPage - 1) * PAGE_SIZE;
    return filteredZipCodes.slice(start, start + PAGE_SIZE);
  }, [filteredZipCodes, currentPage]);

  // Reset to page 1 when search/filter changes
  const handleSearchChange = useCallback((val: string) => {
    setSearchQuery(val);
    setCurrentPage(1);
  }, []);

  const handleFilterChange = useCallback((val: string) => {
    setStatusFilter(val);
    setCurrentPage(1);
  }, []);

  const handleCheck = useCallback(() => {
    if (!checkZip.trim()) return;
    const fd = new FormData();
    fd.set("intent", "check");
    fd.set("checkZip", checkZip);
    fetcher.submit(fd, { method: "POST" });
  }, [checkZip, fetcher]);

  const handleAdd = useCallback(() => {
    if (!newZip.trim()) return;
    const fd = new FormData();
    fd.set("intent", "add");
    fd.set("zipCode", newZip);
    fd.set("label", newLabel);
    fd.set("zone", newZone);
    fd.set("message", newMessage);
    fd.set("eta", newEta);
    fd.set("type", newType);
    fetcher.submit(fd, { method: "POST" });
    if (!actionError) {
      setNewZip("");
      setNewLabel("");
      setNewZone("");
      setNewMessage("");
      setNewEta("");
      setNewType("allowed");
      setAddModalOpen(false);
    }
  }, [newZip, newLabel, newZone, newMessage, newEta, newType, fetcher, actionError]);

  const handleDelete = useCallback(
    (id: string) => {
      const fd = new FormData();
      fd.set("intent", "delete");
      fd.set("id", id);
      fetcher.submit(fd, { method: "POST" });
      shopify.toast.show("Zip code removed");
    },
    [fetcher, shopify],
  );

  const handleToggle = useCallback(
    (id: string, isActive: boolean) => {
      const fd = new FormData();
      fd.set("intent", "toggle");
      fd.set("id", id);
      fd.set("isActive", String(isActive));
      fetcher.submit(fd, { method: "POST" });
    },
    [fetcher],
  );

  const handleImport = useCallback(() => {
    const dataToImport = csvText.trim();
    if (!dataToImport) return;
    const fd = new FormData();
    fd.set("intent", "bulk-import");
    fd.set("csvData", dataToImport);
    fetcher.submit(fd, { method: "POST" });
  }, [csvText, fetcher]);

  const handleFileUpload = useCallback(
    (_files: File[], acceptedFiles: File[]) => {
      if (acceptedFiles.length > 0) {
        const file = acceptedFiles[0];
        setImportFile(file);
        const reader = new FileReader();
        reader.onload = (e) => {
          const text = e.target?.result;
          if (typeof text === "string") {
            setCsvText(text);
          }
        };
        reader.readAsText(file);
      }
    },
    [],
  );

  const handleExport = useCallback(() => {
    const fd = new FormData();
    fd.set("intent", "export");
    fetcher.submit(fd, { method: "POST" });
  }, [fetcher]);

  // Trigger download when export data arrives
  const exportCsv =
    fetcher.data &&
    "action" in fetcher.data &&
    fetcher.data.action === "export" &&
    "csv" in fetcher.data
      ? (fetcher.data.csv as string)
      : null;

  if (exportCsv) {
    const blob = new Blob([exportCsv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "zip-codes.csv";
    a.click();
    URL.revokeObjectURL(url);
  }

  const typeOptions = [
    { label: "Allowed — permit this zip code", value: "allowed" },
    ...(limits.allowBlocked
      ? [{ label: "Blocked — deny this zip code", value: "blocked" }]
      : []),
  ];

  const filterOptions = [
    { label: "All", value: "all" },
    { label: "Allowed", value: "allowed" },
    { label: "Blocked", value: "blocked" },
  ];

  const tableRows = paginatedZipCodes.map((z) => [
    <Text as="span" fontWeight="bold" key={`zip-${z.id}`}>
      {z.zipCode}
    </Text>,
    z.zone || (
      <Text as="span" tone="subdued">
        —
      </Text>
    ),
    <InlineStack gap="300" blockAlign="center" key={`status-${z.id}`}>
      <button
        onClick={() => handleToggle(z.id, z.isActive)}
        style={{
          width: "44px",
          height: "24px",
          borderRadius: "12px",
          border: "none",
          cursor: "pointer",
          position: "relative",
          backgroundColor: z.isActive ? "#2e7d32" : "#ccc",
          transition: "background-color 0.2s",
          padding: 0,
        }}
        aria-label={z.isActive ? "Deactivate" : "Activate"}
      >
        <span
          style={{
            position: "absolute",
            top: "2px",
            left: z.isActive ? "22px" : "2px",
            width: "20px",
            height: "20px",
            borderRadius: "50%",
            backgroundColor: "#fff",
            transition: "left 0.2s",
            boxShadow: "0 1px 3px rgba(0,0,0,0.3)",
          }}
        />
      </button>
      <Badge tone={z.type === "allowed" ? "success" : "critical"}>
        {z.type === "allowed" ? "Allow" : "Block"}
      </Badge>
    </InlineStack>,
    z.message || (
      <Text as="span" tone="subdued">
        —
      </Text>
    ),
    z.eta || (
      <Text as="span" tone="subdued">
        —
      </Text>
    ),
    <Tooltip content="Delete zip code" key={`del-${z.id}`}>
      <Button
        size="slim"
        tone="critical"
        variant="tertiary"
        onClick={() => handleDelete(z.id)}
        icon={DeleteIcon}
        accessibilityLabel="Delete"
      />
    </Tooltip>,
  ]);

  return (
    <Page
      title="Zip Code Checker"
      subtitle="Manage allowed and blocked zip codes for your store"
      primaryAction={
        atZipLimit
          ? {
              content: "Upgrade Plan",
              icon: StarIcon,
              onAction: () => navigate("/app/pricing"),
            }
          : {
              content: "Add Zip Code",
              icon: PlusIcon,
              onAction: () => setAddModalOpen(true),
            }
      }
    >
      <Layout>
        {/* Upgrade banner for free plan */}
        {isFreePlan && (
          <Layout.Section>
            <CalloutCard
              title="You're on the Free plan"
              illustration="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
              primaryAction={{
                content: "View pricing plans",
                onAction: () => navigate("/app/pricing"),
              }}
            >
              <p>
                Free plan includes up to {limits.maxZipCodes} zip codes
                (allowed only). Upgrade to Pro for unlimited zip codes, blocked
                zip codes, and more.
              </p>
            </CalloutCard>
          </Layout.Section>
        )}

        {/* Zip limit warning */}
        {atZipLimit && (
          <Layout.Section>
            <Banner
              title="Zip code limit reached"
              tone="warning"
              action={{
                content: "Upgrade to Pro",
                onAction: () => navigate("/app/pricing"),
              }}
            >
              You have reached the {limits.maxZipCodes} zip code limit for the
              Free plan. Upgrade to Pro for unlimited zip codes.
            </Banner>
          </Layout.Section>
        )}

        {/* Stats Row */}
        <Layout.Section>
          <InlineStack gap="400" wrap>
            <Box
              padding="400"
              background="bg-surface"
              borderWidth="025"
              borderColor="border"
              borderRadius="200"
              minWidth="160px"
            >
              <BlockStack gap="100">
                <Text as="p" tone="subdued" variant="bodyMd">
                  Total Zip Codes
                </Text>
                <InlineStack gap="200" blockAlign="center">
                  <Text as="p" variant="headingXl" fontWeight="bold">
                    {stats.total}
                  </Text>
                  {limits.maxZipCodes !== Infinity && (
                    <Text as="p" tone="subdued" variant="bodySm">
                      / {limits.maxZipCodes}
                    </Text>
                  )}
                </InlineStack>
              </BlockStack>
            </Box>
            <Box
              padding="400"
              background="bg-surface-success"
              borderWidth="025"
              borderColor="border-success"
              borderRadius="200"
              minWidth="160px"
            >
              <BlockStack gap="100">
                <Text as="p" tone="success" variant="bodyMd">
                  Allowed
                </Text>
                <Text
                  as="p"
                  variant="headingXl"
                  fontWeight="bold"
                  tone="success"
                >
                  {stats.allowed}
                </Text>
              </BlockStack>
            </Box>
            <Box
              padding="400"
              background="bg-surface-critical"
              borderWidth="025"
              borderColor="border-critical"
              borderRadius="200"
              minWidth="160px"
            >
              <BlockStack gap="100">
                <Text as="p" tone="critical" variant="bodyMd">
                  Blocked
                </Text>
                <Text
                  as="p"
                  variant="headingXl"
                  fontWeight="bold"
                  tone="critical"
                >
                  {stats.blocked}
                </Text>
                {isFreePlan && <Badge tone="attention">Pro+</Badge>}
              </BlockStack>
            </Box>
            <Box
              padding="400"
              background="bg-surface"
              borderWidth="025"
              borderColor="border"
              borderRadius="200"
              minWidth="160px"
            >
              <BlockStack gap="100">
                <Text as="p" tone="subdued" variant="bodyMd">
                  Active
                </Text>
                <Text as="p" variant="headingXl" fontWeight="bold">
                  {stats.active}
                </Text>
              </BlockStack>
            </Box>
            <Box
              padding="400"
              background="bg-surface"
              borderWidth="025"
              borderColor="border"
              borderRadius="200"
              minWidth="160px"
            >
              <BlockStack gap="100">
                <Text as="p" tone="subdued" variant="bodyMd">
                  Current Plan
                </Text>
                <Badge
                  tone={
                    subscription.planTier === "ultimate"
                      ? "attention"
                      : subscription.planTier === "pro"
                        ? "info"
                        : "enabled"
                  }
                >
                  {subscription.planTier === "ultimate"
                    ? "Ultimate"
                    : subscription.planTier === "pro"
                      ? "Pro"
                      : "Free"}
                </Badge>
              </BlockStack>
            </Box>
          </InlineStack>
        </Layout.Section>

        {/* Zip Code Checker Tool */}
        <Layout.Section>
          <Card>
            <BlockStack gap="400">
              <BlockStack gap="100">
                <Text as="h2" variant="headingMd">
                  Check a Zip Code
                </Text>
                <Text as="p" tone="subdued" variant="bodyMd">
                  Enter a zip code to instantly see if it&apos;s allowed or
                  blocked.
                </Text>
              </BlockStack>

              <InlineStack gap="300" blockAlign="end">
                <div
                  style={{ flex: 1 }}
                  onKeyDown={(e: React.KeyboardEvent) => {
                    if (e.key === "Enter") handleCheck();
                  }}
                >
                  <TextField
                    label="Zip code"
                    value={checkZip}
                    onChange={setCheckZip}
                    placeholder="e.g. 90210"
                    autoComplete="off"
                    labelHidden
                    prefix={<Icon source={SearchIcon} />}
                    connectedRight={
                      <Button
                        onClick={handleCheck}
                        loading={isCheckLoading}
                        variant="primary"
                      >
                        Check
                      </Button>
                    }
                  />
                </div>
              </InlineStack>

              {checkResult && (
                <Banner
                  tone={
                    !checkResult.found
                      ? "warning"
                      : checkResult.record?.type === "allowed"
                        ? "success"
                        : "critical"
                  }
                >
                  {!checkResult.found ? (
                    <Text as="p">
                      <strong>{checkResult.zipCode}</strong> is{" "}
                      <strong>not found</strong> in your zip code list.
                    </Text>
                  ) : checkResult.record?.type === "allowed" ? (
                    <Text as="p">
                      <strong>{checkResult.zipCode}</strong> is{" "}
                      <strong>allowed</strong>
                      {checkResult.record.zone
                        ? ` — Zone: ${checkResult.record.zone}`
                        : ""}
                      {checkResult.record.message
                        ? ` — ${checkResult.record.message}`
                        : ""}
                      {checkResult.record.eta
                        ? ` (ETA: ${checkResult.record.eta})`
                        : ""}
                      .{" "}
                      {!checkResult.record.isActive && (
                        <em>(Currently inactive)</em>
                      )}
                    </Text>
                  ) : (
                    <Text as="p">
                      <strong>{checkResult.zipCode}</strong> is{" "}
                      <strong>blocked</strong>
                      {checkResult.record?.zone
                        ? ` — Zone: ${checkResult.record.zone}`
                        : ""}
                      {checkResult.record?.message
                        ? ` — ${checkResult.record.message}`
                        : ""}
                      .{" "}
                      {!checkResult.record?.isActive && (
                        <em>(Currently inactive)</em>
                      )}
                    </Text>
                  )}
                </Banner>
              )}
            </BlockStack>
          </Card>
        </Layout.Section>

        {/* Zip Code List */}
        <Layout.Section>
          <Card padding="0">
            {/* Toolbar: Search, Filter, Import, Export, Add */}
            <Box padding="400">
              <InlineStack gap="300" align="space-between" blockAlign="center" wrap>
                <InlineStack gap="300" blockAlign="center" wrap>
                  <div style={{ minWidth: "260px" }}>
                    <TextField
                      label="Search zip codes"
                      labelHidden
                      value={searchQuery}
                      onChange={handleSearchChange}
                      placeholder="Search zip codes..."
                      autoComplete="off"
                      prefix={<Icon source={SearchIcon} />}
                      clearButton
                      onClearButtonClick={() => handleSearchChange("")}
                    />
                  </div>
                  <div style={{ minWidth: "120px" }}>
                    <Select
                      label="Filter"
                      labelHidden
                      options={filterOptions}
                      value={statusFilter}
                      onChange={handleFilterChange}
                    />
                  </div>
                </InlineStack>
                <InlineStack gap="200">
                  <Button
                    icon={ImportIcon}
                    onClick={() => setImportModalOpen(true)}
                  >
                    Import CSV
                  </Button>
                  <Button icon={ExportIcon} onClick={handleExport}>
                    Export
                  </Button>
                  <Button
                    variant="primary"
                    icon={atZipLimit ? StarIcon : PlusIcon}
                    onClick={() =>
                      atZipLimit
                        ? navigate("/app/pricing")
                        : setAddModalOpen(true)
                    }
                    tone={atZipLimit ? "success" : undefined}
                  >
                    {atZipLimit ? "Upgrade Plan" : "Add Zip Code"}
                  </Button>
                </InlineStack>
              </InlineStack>
            </Box>
            <Divider />

            {(zipCodes as ZipCodeRecord[]).length === 0 ? (
              <EmptyState
                heading="No zip codes added yet"
                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
                action={{
                  content: "Add your first zip code",
                  onAction: () => setAddModalOpen(true),
                }}
                secondaryAction={{
                  content: "Import from CSV",
                  onAction: () => setImportModalOpen(true),
                }}
              >
                <p>
                  Add zip codes to control which areas are allowed or blocked
                  for your store. You can add them one by one or import a CSV
                  file.
                </p>
              </EmptyState>
            ) : filteredZipCodes.length === 0 ? (
              <Box padding="600">
                <BlockStack gap="200" inlineAlign="center">
                  <Text as="p" tone="subdued" alignment="center">
                    No zip codes match your search.
                  </Text>
                  <Button
                    variant="plain"
                    onClick={() => {
                      setSearchQuery("");
                      setStatusFilter("all");
                    }}
                  >
                    Clear filters
                  </Button>
                </BlockStack>
              </Box>
            ) : (
              <>
                <DataTable
                  columnContentTypes={[
                    "text",
                    "text",
                    "text",
                    "text",
                    "text",
                    "text",
                  ]}
                  headings={[
                    "Zip Code",
                    "Zone",
                    "Status",
                    "Message",
                    "ETA",
                    "Actions",
                  ]}
                  rows={tableRows}
                  hoverable
                />
                {totalPages > 1 && (
                  <Box padding="400">
                    <InlineStack align="center" blockAlign="center" gap="300">
                      <Pagination
                        hasPrevious={currentPage > 1}
                        onPrevious={() =>
                          setCurrentPage((p) => Math.max(1, p - 1))
                        }
                        hasNext={currentPage < totalPages}
                        onNext={() =>
                          setCurrentPage((p) => Math.min(totalPages, p + 1))
                        }
                      />
                      <Text as="span" tone="subdued" variant="bodySm">
                        Page {currentPage} of {totalPages} ({filteredZipCodes.length} results)
                      </Text>
                    </InlineStack>
                  </Box>
                )}
              </>
            )}
          </Card>
        </Layout.Section>
      </Layout>

      {/* Add Zip Code Modal */}
      <Modal
        open={addModalOpen}
        onClose={() => {
          setAddModalOpen(false);
          setNewZip("");
          setNewLabel("");
          setNewZone("");
          setNewMessage("");
          setNewEta("");
          setNewType("allowed");
        }}
        title="Add Zip Code"
        primaryAction={{
          content: "Add Zip Code",
          onAction: handleAdd,
          loading: isAddLoading,
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => {
              setAddModalOpen(false);
              setNewZip("");
              setNewLabel("");
              setNewZone("");
              setNewMessage("");
              setNewEta("");
              setNewType("allowed");
            },
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            {actionError && (
              <Banner
                tone="critical"
                action={
                  upgradeRequired
                    ? {
                        content: "View Pricing Plans",
                        onAction: () => {
                          setAddModalOpen(false);
                          navigate("/app/pricing");
                        },
                      }
                    : undefined
                }
              >
                {actionError}
              </Banner>
            )}
            <TextField
              label="Zip Code"
              value={newZip}
              onChange={setNewZip}
              placeholder="e.g. 90210"
              autoComplete="off"
              helpText="Enter a 5-digit US zip code or postal code."
            />
            <InlineStack gap="300">
              <div style={{ flex: 1 }}>
                <TextField
                  label="Zone"
                  value={newZone}
                  onChange={setNewZone}
                  placeholder="e.g. Manhattan, Beverly Hills"
                  autoComplete="off"
                  helpText="The delivery zone or area name."
                />
              </div>
              <div style={{ flex: 1 }}>
                <Select
                  label="Status"
                  options={typeOptions}
                  value={newType}
                  onChange={setNewType}
                  helpText={
                    isFreePlan && !limits.allowBlocked
                      ? "Blocked zip codes require Pro or Ultimate plan."
                      : "Allow or block this zip code."
                  }
                />
              </div>
            </InlineStack>
            <TextField
              label="Message"
              value={newMessage}
              onChange={setNewMessage}
              placeholder="e.g. Delivery available!, Sorry we don't deliver here"
              autoComplete="off"
              helpText="Custom message shown to customers for this zip code."
            />
            <InlineStack gap="300">
              <div style={{ flex: 1 }}>
                <TextField
                  label="ETA"
                  value={newEta}
                  onChange={setNewEta}
                  placeholder="e.g. 2-3 days"
                  autoComplete="off"
                  helpText="Estimated delivery time."
                />
              </div>
              <div style={{ flex: 1 }}>
                <TextField
                  label="Label (optional)"
                  value={newLabel}
                  onChange={setNewLabel}
                  placeholder="e.g. Downtown LA"
                  autoComplete="off"
                  helpText="Internal label for your reference."
                />
              </div>
            </InlineStack>
            {isFreePlan && !limits.allowBlocked && (
              <Banner tone="info">
                <InlineStack gap="200" blockAlign="center">
                  <Text as="span" variant="bodySm">
                    Want to block zip codes?{" "}
                  </Text>
                  <Button
                    variant="plain"
                    onClick={() => {
                      setAddModalOpen(false);
                      navigate("/app/pricing");
                    }}
                  >
                    Upgrade to Pro
                  </Button>
                </InlineStack>
              </Banner>
            )}
          </BlockStack>
        </Modal.Section>
      </Modal>

      {/* Import CSV Modal */}
      <Modal
        open={importModalOpen}
        onClose={() => {
          setImportModalOpen(false);
          setCsvText("");
          setImportFile(null);
        }}
        title="Import Zip Codes from CSV"
        primaryAction={{
          content: isImportLoading ? "Importing..." : "Import",
          onAction: handleImport,
          loading: isImportLoading,
          disabled: !csvText.trim(),
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => {
              setImportModalOpen(false);
              setCsvText("");
              setImportFile(null);
            },
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            {importResult && (
              <Banner
                tone={
                  importResult.errors && (importResult.errors as string[]).length > 0
                    ? "warning"
                    : "success"
                }
              >
                <Text as="p">
                  Imported <strong>{importResult.imported as number}</strong> zip
                  codes.
                  {(importResult.skipped as number) > 0 &&
                    ` Skipped ${importResult.skipped} entries.`}
                </Text>
                {importResult.errors &&
                  (importResult.errors as string[]).map((e, i) => (
                    <Text as="p" key={i} tone="critical">
                      {e}
                    </Text>
                  ))}
              </Banner>
            )}

            <Text as="p" variant="bodyMd">
              Upload a CSV file or paste CSV data below. The expected format is:
            </Text>
            <Box
              padding="300"
              background="bg-surface-secondary"
              borderRadius="200"
            >
              <Text as="p" variant="bodySm" fontWeight="semibold">
                Zip Code, Zone, Status, Message, ETA
              </Text>
              <Text as="p" variant="bodySm" tone="subdued">
                10001, Manhattan, allowed, Delivery available!, 2-3 days
              </Text>
              <Text as="p" variant="bodySm" tone="subdued">
                33101, Miami, blocked, Sorry we don&apos;t deliver here,
              </Text>
            </Box>

            <DropZone
              accept=".csv,text/csv"
              type="file"
              onDrop={handleFileUpload}
              allowMultiple={false}
            >
              {importFile ? (
                <Box padding="400">
                  <InlineStack gap="200" blockAlign="center" align="center">
                    <Text as="p" variant="bodyMd" fontWeight="semibold">
                      {importFile.name}
                    </Text>
                    <Badge tone="success">Ready</Badge>
                  </InlineStack>
                </Box>
              ) : (
                <DropZone.FileUpload actionHint="Accepts .csv files" />
              )}
            </DropZone>

            <Text as="p" variant="bodySm" tone="subdued">
              Or paste your CSV data directly:
            </Text>
            <TextField
              label="CSV data"
              labelHidden
              value={csvText}
              onChange={setCsvText}
              multiline={6}
              placeholder="10001, Manhattan, allowed, Delivery available!, 2-3 days"
              autoComplete="off"
            />
          </BlockStack>
        </Modal.Section>
      </Modal>
    </Page>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
