            >
              <Text as="p" variant="bodyMd">
                Free plan includes up to {limits.maxZipCodes} zip codes
                (allowed only). Upgrade to Pro for unlimited zip codes, blocked
                zip codes, and more.
              </Text>
            </Banner>
          </Layout.Section>
        )}

        {/* Zip limit warning */}
        {atZipLimit && (
          <Layout.Section>
            <Banner
              title="Zip code limit reached"
              tone="warning"
              action={{
                content: "Upgrade to Pro",
                onAction: () => navigate("/app/pricing"),
              }}
            >
              You have reached the {limits.maxZipCodes} zip code limit for the
              Free plan. Upgrade to Pro for unlimited zip codes.
            </Banner>
          </Layout.Section>
        )}

        {/* Stats Row */}
        <Layout.Section>
          <InlineStack gap="400" wrap>
            <Box
              padding="400"
              background="bg-surface"
              borderWidth="025"
              borderColor="border"
              borderRadius="200"
              minWidth="160px"
            >
              <BlockStack gap="100">
                <Text as="p" tone="subdued" variant="bodyMd">
                  Total Zip Codes
                </Text>
                <InlineStack gap="200" blockAlign="center">
                  <Text as="p" variant="headingXl" fontWeight="bold">
                    {stats.total}
                  </Text>
                  {limits.maxZipCodes !== Infinity && (
                    <Text as="p" tone="subdued" variant="bodySm">
                      / {limits.maxZipCodes}
                    </Text>
                  )}
                </InlineStack>
              </BlockStack>
            </Box>
            <Box
              padding="400"
              background="bg-surface-success"
              borderWidth="025"
              borderColor="border-success"
              borderRadius="200"
              minWidth="160px"
            >
              <BlockStack gap="100">
                <Text as="p" tone="success" variant="bodyMd">
                  Allowed
                </Text>
                <Text
                  as="p"
                  variant="headingXl"
                  fontWeight="bold"
                  tone="success"
                >
                  {stats.allowed}
                </Text>
              </BlockStack>
            </Box>
            <Box
              padding="400"
              background="bg-surface-critical"
              borderWidth="025"
              borderColor="border-critical"
              borderRadius="200"
              minWidth="160px"
            >
              <BlockStack gap="100">
                <Text as="p" tone="critical" variant="bodyMd">
                  Blocked
                </Text>
                <Text
                  as="p"
                  variant="headingXl"
                  fontWeight="bold"
                  tone="critical"
                >
                  {stats.blocked}
                </Text>
                {isFreePlan && <Badge tone="attention">Pro+</Badge>}
              </BlockStack>
            </Box>
            <Box
              padding="400"
              background="bg-surface"
              borderWidth="025"
              borderColor="border"
              borderRadius="200"
              minWidth="160px"
            >
              <BlockStack gap="100">
                <Text as="p" tone="subdued" variant="bodyMd">
                  Active
                </Text>
                <Text as="p" variant="headingXl" fontWeight="bold">
                  {stats.active}
                </Text>
              </BlockStack>
            </Box>
            <Box
              padding="400"
              background="bg-surface"
              borderWidth="025"
              borderColor="border"
              borderRadius="200"
              minWidth="160px"
            >
              <BlockStack gap="100">
                <Text as="p" tone="subdued" variant="bodyMd">
                  Current Plan
                </Text>
                <Badge
                  tone={
                    subscription.planTier === "ultimate"
                      ? "attention"
                      : subscription.planTier === "pro"
                        ? "info"
                        : "enabled"
                  }
                >
                  {subscription.planTier === "ultimate"
                    ? "Ultimate"
                    : subscription.planTier === "pro"
                      ? "Pro"
                      : "Free"}
                </Badge>
              </BlockStack>
            </Box>
          </InlineStack>
        </Layout.Section>

        {/* Zip Code Checker Tool */}
        <Layout.Section>
          <Card>
            <BlockStack gap="400">
              <BlockStack gap="100">
                <Text as="h2" variant="headingMd">
                  Check a Zip Code
                </Text>
                <Text as="p" tone="subdued" variant="bodyMd">
                  Enter a zip code to instantly see if it&apos;s allowed or
                  blocked.
                </Text>
              </BlockStack>

              <InlineStack gap="300" blockAlign="end">
                <div
                  style={{ flex: 1 }}
                  onKeyDown={(e: React.KeyboardEvent) => {
                    if (e.key === "Enter") handleCheck();
                  }}
                >
                  <TextField
                    label="Zip code"
                    value={checkZip}
                    onChange={setCheckZip}
                    placeholder="e.g. 90210"
                    autoComplete="off"
                    labelHidden
                    prefix={<Icon source={SearchIcon} />}
                    connectedRight={
                      <Button
                        onClick={handleCheck}
                        loading={isCheckLoading}
                        variant="primary"
                      >
                        Check
                      </Button>
                    }
                  />
                </div>
              </InlineStack>

              {checkResult && (
                <Banner
                  tone={
                    !checkResult.found
                      ? "warning"
                      : checkResult.record?.type === "allowed"
                        ? "success"
                        : "critical"
                  }
                >
                  {!checkResult.found ? (
                    <Text as="p">
                      <strong>{checkResult.zipCode}</strong> is{" "}
                      <strong>not found</strong> in your zip code list.
                    </Text>
                  ) : checkResult.record?.type === "allowed" ? (
                    <Text as="p">
                      <strong>{checkResult.zipCode}</strong> is{" "}
                      <strong>allowed</strong>
                      {checkResult.record.zone
                        ? ` — Zone: ${checkResult.record.zone}`
                        : ""}
                      {checkResult.record.message
                        ? ` — ${checkResult.record.message}`
                        : ""}
                      {checkResult.record.eta
                        ? ` (ETA: ${checkResult.record.eta})`
                        : ""}
                      .{" "}
                      {!checkResult.record.isActive && (
                        <em>(Currently inactive)</em>
                      )}
                    </Text>
                  ) : (
                    <Text as="p">
                      <strong>{checkResult.zipCode}</strong> is{" "}
                      <strong>blocked</strong>
                      {checkResult.record?.zone
                        ? ` — Zone: ${checkResult.record.zone}`
                        : ""}
                      {checkResult.record?.message
                        ? ` — ${checkResult.record.message}`
                        : ""}
                      .{" "}
                      {!checkResult.record?.isActive && (
                        <em>(Currently inactive)</em>
                      )}
                    </Text>
                  )}
                </Banner>
              )}
            </BlockStack>
          </Card>
        </Layout.Section>

        {/* Zip Code List */}
        <Layout.Section>
          <Card padding="0">
            {/* Toolbar: Search, Filter, Import, Export, Add */}
            <Box padding="400">
              <InlineStack gap="300" align="space-between" blockAlign="center" wrap>
                <InlineStack gap="300" blockAlign="center" wrap>
                  <div style={{ minWidth: "260px" }}>
                    <TextField
                      label="Search zip codes"
                      labelHidden
                      value={searchQuery}
                      onChange={handleSearchChange}
                      placeholder="Search zip codes..."
                      autoComplete="off"
                      prefix={<Icon source={SearchIcon} />}
                      clearButton
                      onClearButtonClick={() => handleSearchChange("")}
                    />
                  </div>
                  <div style={{ minWidth: "120px" }}>
                    <Select
                      label="Filter"
                      labelHidden
                      options={filterOptions}
                      value={statusFilter}
                      onChange={handleFilterChange}
                    />
                  </div>
                </InlineStack>
                <InlineStack gap="200">
                  <Button
                    icon={ImportIcon}
                    onClick={() => setImportModalOpen(true)}
                  >
                    Import CSV
                  </Button>
                  <Button icon={ExportIcon} onClick={handleExport}>
                    Export
                  </Button>
                  <Button
                    variant="primary"
                    icon={atZipLimit ? StarIcon : PlusIcon}
                    onClick={() =>
                      atZipLimit
                        ? navigate("/app/pricing")
                        : setAddModalOpen(true)
                    }
                    tone={atZipLimit ? "success" : undefined}
                  >
                    {atZipLimit ? "Upgrade Plan" : "Add Zip Code"}
                  </Button>
                </InlineStack>
              </InlineStack>
            </Box>
            <Divider />

            {(zipCodes as ZipCodeRecord[]).length === 0 ? (
              <EmptyState
                heading="No zip codes added yet"
                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
                action={{
                  content: "Add your first zip code",
                  onAction: () => setAddModalOpen(true),
                }}
                secondaryAction={{
                  content: "Import from CSV",
                  onAction: () => setImportModalOpen(true),
                }}
              >
                <p>
                  Add zip codes to control which areas are allowed or blocked
                  for your store. You can add them one by one or import a CSV
                  file.
                </p>
              </EmptyState>
            ) : filteredZipCodes.length === 0 ? (
              <Box padding="600">
                <BlockStack gap="200" inlineAlign="center">
                  <Text as="p" tone="subdued" alignment="center">
                    No zip codes match your search.
                  </Text>
                  <Button
                    variant="plain"
                    onClick={() => {
                      setSearchQuery("");
                      setStatusFilter("all");
                    }}
                  >
                    Clear filters
                  </Button>
                </BlockStack>
              </Box>
            ) : (
              <>
                <DataTable
                  columnContentTypes={[
                    "text",
                    "text",
                    "text",
                    "text",
                    "text",
                    "text",
                  ]}
                  headings={[
                    "Zip Code",
                    "Zone",
                    "Status",
                    "Message",
                    "ETA",
                    "Actions",
                  ]}
                  rows={tableRows}
                  hoverable
                />
                {totalPages > 1 && (
                  <Box padding="400">
                    <InlineStack align="center" blockAlign="center" gap="300">
                      <Pagination
                        hasPrevious={currentPage > 1}
                        onPrevious={() =>
                          setCurrentPage((p) => Math.max(1, p - 1))
                        }
                        hasNext={currentPage < totalPages}
                        onNext={() =>
                          setCurrentPage((p) => Math.min(totalPages, p + 1))
                        }
                      />
                      <Text as="span" tone="subdued" variant="bodySm">
                        Page {currentPage} of {totalPages} ({filteredZipCodes.length} results)
                      </Text>
                    </InlineStack>
                  </Box>
                )}
              </>
            )}
          </Card>
        </Layout.Section>
      </Layout>

      {/* Add Zip Code Modal */}
      <Modal
        open={addModalOpen}
        onClose={() => {
          setAddModalOpen(false);
          setNewZip("");
          setNewLabel("");
          setNewZone("");
          setNewMessage("");
          setNewEta("");
          setNewType("allowed");
        }}
        title="Add Zip Code"
        primaryAction={{
          content: "Add Zip Code",
          onAction: handleAdd,
          loading: isAddLoading,
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => {
              setAddModalOpen(false);
              setNewZip("");
              setNewLabel("");
              setNewZone("");
              setNewMessage("");
              setNewEta("");
              setNewType("allowed");
            },
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            {actionError && (
              <Banner
                tone="critical"
                action={
                  upgradeRequired
                    ? {
                        content: "View Pricing Plans",
                        onAction: () => {
                          setAddModalOpen(false);
                          navigate("/app/pricing");
                        },
                      }
                    : undefined
                }
              >
                {actionError}
              </Banner>
            )}
            <TextField
              label="Zip Code"
              value={newZip}
              onChange={setNewZip}
              placeholder="e.g. 90210"
              autoComplete="off"
              helpText="Enter a 5-digit US zip code or postal code."
            />
            <InlineStack gap="300">
              <div style={{ flex: 1 }}>
                <TextField
                  label="Zone"
                  value={newZone}
                  onChange={setNewZone}
                  placeholder="e.g. Manhattan, Beverly Hills"
                  autoComplete="off"
                  helpText="The delivery zone or area name."
                />
              </div>
              <div style={{ flex: 1 }}>
                <Select
                  label="Status"
                  options={typeOptions}
                  value={newType}
                  onChange={setNewType}
                  helpText={
                    isFreePlan && !limits.allowBlocked
                      ? "Blocked zip codes require Pro or Ultimate plan."
                      : "Allow or block this zip code."
                  }
                />
              </div>
            </InlineStack>
            <TextField
              label="Message"
              value={newMessage}
              onChange={setNewMessage}
              placeholder="e.g. Delivery available!, Sorry we don't deliver here"
              autoComplete="off"
              helpText="Custom message shown to customers for this zip code."
            />
            <InlineStack gap="300">
              <div style={{ flex: 1 }}>
                <TextField
                  label="ETA"
                  value={newEta}
                  onChange={setNewEta}
                  placeholder="e.g. 2-3 days"
                  autoComplete="off"
                  helpText="Estimated delivery time."
                />
              </div>
              <div style={{ flex: 1 }}>
                <TextField
                  label="Label (optional)"
                  value={newLabel}
                  onChange={setNewLabel}
                  placeholder="e.g. Downtown LA"
                  autoComplete="off"
                  helpText="Internal label for your reference."
                />
              </div>
            </InlineStack>
            {isFreePlan && !limits.allowBlocked && (
              <Banner tone="info">
                <InlineStack gap="200" blockAlign="center">
                  <Text as="span" variant="bodySm">
                    Want to block zip codes?{" "}
                  </Text>
                  <Button
                    variant="plain"
                    onClick={() => {
                      setAddModalOpen(false);
                      navigate("/app/pricing");
                    }}
                  >
                    Upgrade to Pro
                  </Button>
                </InlineStack>
              </Banner>
            )}
          </BlockStack>
        </Modal.Section>
      </Modal>

      {/* Import CSV Modal */}
      <Modal
        open={importModalOpen}
        onClose={() => {
          setImportModalOpen(false);
          setCsvText("");
          setImportFile(null);
        }}
        title="Import Zip Codes from CSV"
        primaryAction={{
          content: isImportLoading ? "Importing..." : "Import",
          onAction: handleImport,
          loading: isImportLoading,
          disabled: !csvText.trim(),
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => {
              setImportModalOpen(false);
              setCsvText("");
              setImportFile(null);
            },
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            {importResult && (
              <Banner
                tone={
                  importResult.errors && (importResult.errors as string[]).length > 0
                    ? "warning"
                    : "success"
                }
              >
                <Text as="p">
                  Imported <strong>{importResult.imported as number}</strong> zip
                  codes.
                  {(importResult.skipped as number) > 0 &&
                    ` Skipped ${importResult.skipped} entries.`}
                </Text>
                {importResult.errors &&
                  (importResult.errors as string[]).map((e, i) => (
                    <Text as="p" key={i} tone="critical">
                      {e}
                    </Text>
                  ))}
              </Banner>
            )}

            <Text as="p" variant="bodyMd">
              Upload a CSV file or paste CSV data below. The expected format is:
            </Text>
            <Box
              padding="300"
              background="bg-surface-secondary"
              borderRadius="200"
            >
              <Text as="p" variant="bodySm" fontWeight="semibold">
                Zip Code, Zone, Status, Message, ETA
              </Text>
              <Text as="p" variant="bodySm" tone="subdued">
                10001, Manhattan, allowed, Delivery available!, 2-3 days
              </Text>
              <Text as="p" variant="bodySm" tone="subdued">
                33101, Miami, blocked, Sorry we don&apos;t deliver here,
              </Text>
            </Box>

            <DropZone
              accept=".csv,text/csv"
              type="file"
              onDrop={handleFileUpload}
              allowMultiple={false}
            >
              {importFile ? (
                <Box padding="400">
                  <InlineStack gap="200" blockAlign="center" align="center">
                    <Text as="p" variant="bodyMd" fontWeight="semibold">
                      {importFile.name}
                    </Text>
                    <Badge tone="success">Ready</Badge>
                  </InlineStack>
                </Box>
              ) : (
                <DropZone.FileUpload actionHint="Accepts .csv files" />
              )}
            </DropZone>

            <Text as="p" variant="bodySm" tone="subdued">
              Or paste your CSV data directly:
            </Text>
            <TextField
              label="CSV data"
              labelHidden
              value={csvText}
              onChange={setCsvText}
              multiline={6}
              placeholder="10001, Manhattan, allowed, Delivery available!, 2-3 days"
              autoComplete="off"
            />
          </BlockStack>
        </Modal.Section>
      </Modal>
    </Page>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

import { useState, useCallback } from "react";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import { useFetcher, useLoaderData, useNavigate } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Button,
  TextField,
  Select,
  Checkbox,
  Divider,
  Box,
  Banner,
} from "@shopify/polaris";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  let config = await db.widgetConfig.findUnique({ where: { shop } });

  if (!config) {
    config = await db.widgetConfig.create({ data: { shop } });
  }

  return { config };
};

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent");

  if (intent === "save") {
    const data = {
      position: String(formData.get("position") || "inline"),
      primaryColor: String(formData.get("primaryColor") || "#008060"),
      successColor: String(formData.get("successColor") || "#008060"),
      errorColor: String(formData.get("errorColor") || "#D72C0D"),
      backgroundColor: String(formData.get("backgroundColor") || "#FFFFFF"),
      textColor: String(formData.get("textColor") || "#202223"),
      heading: String(formData.get("heading") || "Check Delivery Availability"),
      placeholder: String(formData.get("placeholder") || "Enter your zip code"),
      buttonText: String(formData.get("buttonText") || "Check"),
      successMessage: String(
        formData.get("successMessage") ||
          "Great news! We deliver to your area.",
      ),
      errorMessage: String(
        formData.get("errorMessage") ||
          "Sorry, we don't deliver to this area yet.",
      ),
      notFoundMessage: String(
        formData.get("notFoundMessage") ||
          "This zip code was not found in our system.",
      ),
      showEta: formData.get("showEta") === "true",
      showZone: formData.get("showZone") === "true",
      showWaitlistOnFailure: formData.get("showWaitlistOnFailure") === "true",
      borderRadius: String(formData.get("borderRadius") || "8"),
      customCss: String(formData.get("customCss") || "") || null,
    };

    await db.widgetConfig.upsert({
      where: { shop },
      create: { shop, ...data },
      update: data,
    });

    return { success: true };
  }

  if (intent === "reset") {
    await db.widgetConfig.upsert({
      where: { shop },
      create: { shop },
      update: {
        position: "inline",
        primaryColor: "#008060",
        successColor: "#008060",
        errorColor: "#D72C0D",
        backgroundColor: "#FFFFFF",
        textColor: "#202223",
        heading: "Check Delivery Availability",
        placeholder: "Enter your zip code",
        buttonText: "Check",
        successMessage: "Great news! We deliver to your area.",
        errorMessage: "Sorry, we don't deliver to this area yet.",
        notFoundMessage: "This zip code was not found in our system.",
        showEta: true,
        showZone: false,
        showWaitlistOnFailure: false,
        borderRadius: "8",
        customCss: null,
      },
    });
    return { success: true, action: "reset" };
  }

  return null;
};

type WidgetConfig = {
  position: string;
  primaryColor: string;
  successColor: string;
  errorColor: string;
  backgroundColor: string;
  textColor: string;
  heading: string;
  placeholder: string;
  buttonText: string;
  successMessage: string;
  errorMessage: string;
  notFoundMessage: string;
  showEta: boolean;
  showZone: boolean;
  showWaitlistOnFailure: boolean;
  borderRadius: string;
  customCss: string | null;
};

export default function WidgetPage() {
  const { config } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();
  const navigate = useNavigate();

  const c = config as WidgetConfig;

  // Form state initialized from DB
  const [position, setPosition] = useState(c.position);
  const [primaryColor, setPrimaryColor] = useState(c.primaryColor);
  const [successColor, setSuccessColor] = useState(c.successColor);
  const [errorColor, setErrorColor] = useState(c.errorColor);
  const [backgroundColor, setBackgroundColor] = useState(c.backgroundColor);
  const [textColor, setTextColor] = useState(c.textColor);
  const [heading, setHeading] = useState(c.heading);
  const [placeholder, setPlaceholder] = useState(c.placeholder);
  const [buttonText, setButtonText] = useState(c.buttonText);
  const [successMessage, setSuccessMessage] = useState(c.successMessage);
  const [errorMessage, setErrorMessage] = useState(c.errorMessage);
  const [notFoundMessage, setNotFoundMessage] = useState(c.notFoundMessage);
  const [showEta, setShowEta] = useState(c.showEta);
  const [showZone, setShowZone] = useState(c.showZone);
  const [showWaitlistOnFailure, setShowWaitlistOnFailure] = useState(
    c.showWaitlistOnFailure,
  );
  const [borderRadius, setBorderRadius] = useState(c.borderRadius);
  const [customCss, setCustomCss] = useState(c.customCss || "");

  // Preview state
  const [previewState, setPreviewState] = useState<
    "idle" | "success" | "error" | "notfound"
  >("idle");

  const isSaving =
    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "save";
  const saved =
    fetcher.data &&
    "success" in fetcher.data &&
    fetcher.data.success &&
    !("action" in fetcher.data);

  const handleSave = useCallback(() => {
    const fd = new FormData();
    fd.set("intent", "save");
    fd.set("position", position);
    fd.set("primaryColor", primaryColor);
    fd.set("successColor", successColor);
    fd.set("errorColor", errorColor);
    fd.set("backgroundColor", backgroundColor);
    fd.set("textColor", textColor);
    fd.set("heading", heading);
    fd.set("placeholder", placeholder);
    fd.set("buttonText", buttonText);
    fd.set("successMessage", successMessage);
    fd.set("errorMessage", errorMessage);
    fd.set("notFoundMessage", notFoundMessage);
    fd.set("showEta", String(showEta));
    fd.set("showZone", String(showZone));
    fd.set("showWaitlistOnFailure", String(showWaitlistOnFailure));
    fd.set("borderRadius", borderRadius);
    fd.set("customCss", customCss);
    fetcher.submit(fd, { method: "POST" });
    shopify.toast.show("Widget settings saved");
