              borderRadius: rad,
              fontSize: "14px",
              outline: "none",
              color: textColor,
              backgroundColor: "#fafbfb",
            }}
          />
          <button
            type="button"
            style={{
              backgroundColor: primaryColor,
              color: "#fff",
              border: "none",
              borderRadius: rad,
              padding: "10px 20px",
              fontSize: "14px",
              fontWeight: 600,
              cursor: "pointer",
            }}
          >
            {buttonText}
          </button>
        </div>

        {resultMessage && (
          <div
            style={{
              padding: "12px",
              borderRadius: rad,
              backgroundColor: `${resultColor}15`,
              borderLeft: `3px solid ${resultColor}`,
              fontSize: "14px",
              color: resultColor,
            }}
          >
            {resultMessage}
            {previewState === "success" && showEta && (
              <div
                style={{
                  marginTop: "4px",
                  fontSize: "13px",
                  opacity: 0.8,
                }}
              >
                Estimated delivery: 2-3 days
              </div>
            )}
            {previewState === "success" && showZone && (
              <div
                style={{
                  marginTop: "4px",
                  fontSize: "13px",
                  opacity: 0.8,
                }}
              >
                Zone: Manhattan
              </div>
            )}
            {(previewState === "error" || previewState === "notfound") &&
              showWaitlistOnFailure && (
                <div style={{ marginTop: "8px" }}>
                  <input
                    type="email"
                    placeholder="Enter your email to join waitlist"
                    readOnly
                    style={{
                      width: "100%",
                      padding: "8px 10px",
                      border: `1px solid ${errorColor}40`,
                      borderRadius: rad,
                      fontSize: "13px",
                      boxSizing: "border-box",
                    }}
                  />
                </div>
              )}
          </div>
        )}
      </div>
    );
  };

  return (
    <Page
      title="Widget Customization"
      subtitle="Customize how the zip code checker looks on your storefront"
      backAction={{ onAction: () => navigate("/app") }}
      primaryAction={{
        content: "Save Changes",
        onAction: handleSave,
        loading: isSaving,
      }}
      secondaryActions={[
        {
          content: "Reset to Defaults",
          onAction: handleReset,
          destructive: true,
        },
      ]}
    >
      <Layout>
        {saved && (
          <Layout.Section>
            <Banner tone="success" title="Settings saved successfully" />
          </Layout.Section>
        )}

        <Layout.Section>
          <InlineStack gap="400" align="start" wrap>
            {/* Settings Column */}
            <div style={{ flex: 1, minWidth: "340px" }}>
              <BlockStack gap="400">
                {/* Layout */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd">
