    textColor,
    heading,
    placeholder,
    buttonText,
    successMessage,
    errorMessage,
    notFoundMessage,
    showEta,
    showZone,
    showWaitlistOnFailure,
    borderRadius,
    customCss,
    fetcher,
    shopify,
  ]);

