    [fetcher],
  );

  const toggleDay = useCallback(
    (day: string) => {
      setSelectedDays((prev) =>
        prev.includes(day) ? prev.filter((d) => d !== day) : [...prev, day],
      );
    },
    [],
  );

  const zoneOptions = [
    { label: "All zones", value: "" },
    ...zones.map((z) => ({ label: z, value: z })),
  ];

  const tableRows = (rules as Rule[]).map((rule) => [
    <InlineStack gap="200" blockAlign="center" key={`name-${rule.id}`}>
      <Text as="span" fontWeight="bold">
        {rule.name}
      </Text>
      <Badge tone={rule.isActive ? "success" : undefined}>
        {rule.isActive ? "Active" : "Inactive"}
      </Badge>
    </InlineStack>,
    rule.zone || "All",
    rule.deliveryFee != null ? `$${rule.deliveryFee.toFixed(2)}` : "Free",
    rule.minOrderAmount != null ? `$${rule.minOrderAmount.toFixed(2)}` : "—",
    rule.estimatedDays || "—",
    rule.daysOfWeek || "All days",
    <InlineStack gap="200" key={`actions-${rule.id}`}>
      <button
        onClick={() => handleToggle(rule.id, rule.isActive)}
        style={{
          width: "40px",
          height: "22px",
          borderRadius: "11px",
          border: "none",
          cursor: "pointer",
          position: "relative",
          backgroundColor: rule.isActive ? "#2e7d32" : "#ccc",
          transition: "background-color 0.2s",
          padding: 0,
        }}
        aria-label={rule.isActive ? "Deactivate" : "Activate"}
      >
        <span
          style={{
            position: "absolute",
            top: "2px",
            left: rule.isActive ? "20px" : "2px",
            width: "18px",
            height: "18px",
            borderRadius: "50%",
            backgroundColor: "#fff",
            transition: "left 0.2s",
            boxShadow: "0 1px 3px rgba(0,0,0,0.3)",
          }}
        />
      </button>
      <Tooltip content="Edit rule">
        <Button
          size="slim"
          variant="tertiary"
          onClick={() => openEdit(rule)}
          icon={EditIcon}
          accessibilityLabel="Edit"
        />
      </Tooltip>
      <Tooltip content="Delete rule">
        <Button
          size="slim"
          variant="tertiary"
          tone="critical"
          onClick={() => handleDelete(rule.id)}
          icon={DeleteIcon}
          accessibilityLabel="Delete"
        />
      </Tooltip>
    </InlineStack>,
  ]);

  return (
    <Page
      title="Delivery Rules"
      subtitle="Configure delivery fees, minimums, schedules, and conditions per zone"
      backAction={{ onAction: () => navigate("/app") }}
      primaryAction={{
        content: "Add Rule",
        icon: PlusIcon,
        onAction: openCreate,
      }}
    >
      <Box paddingBlockEnd="1600">
      <Layout>
        <Layout.Section>
          <Card padding="0">
            {(rules as Rule[]).length === 0 ? (
              <EmptyState
                heading="No delivery rules yet"
                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
                action={{
                  content: "Create your first rule",
                  onAction: openCreate,
                }}
              >
                <p>
                  Delivery rules let you set fees, minimum order amounts,
                  estimated delivery times, and delivery schedules for different
                  zones. Rules are evaluated by priority order.
                </p>
              </EmptyState>
            ) : (
              <DataTable
                columnContentTypes={[
                  "text",
                  "text",
                  "text",
                  "text",
                  "text",
                  "text",
                  "text",
                ]}
                headings={[
                  "Rule Name",
                  "Zone",
                  "Delivery Fee",
                  "Min. Order",
                  "ETA",
                  "Days",
                  "Actions",
                ]}
                rows={tableRows}
                hoverable
              />
            )}
          </Card>
        </Layout.Section>
      </Layout>
      </Box>

      {/* Create / Edit Modal */}
      <Modal
        open={modalOpen}
        onClose={() => {
          setModalOpen(false);
          resetForm();
        }}
        title={editingRule ? "Edit Delivery Rule" : "Create Delivery Rule"}
        primaryAction={{
          content: editingRule ? "Save Changes" : "Create Rule",
          onAction: handleSave,
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => {
              setModalOpen(false);
              resetForm();
            },
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            {actionError && <Banner tone="critical">{actionError}</Banner>}

            <TextField
              label="Rule Name"
              value={name}
              onChange={setName}
              placeholder="e.g. Manhattan Standard Delivery"
              autoComplete="off"
              helpText="A descriptive name for this delivery rule."
            />

            <InlineStack gap="300">
              <div style={{ flex: 1 }}>
                <Select
                  label="Zone"
                  options={zoneOptions}
                  value={zone}
                  onChange={setZone}
                  helpText="Apply this rule to a specific zone, or all zones."
                />
              </div>
              <div style={{ flex: 1 }}>
                <TextField
                  label="Priority"
                  type="number"
                  value={priority}
                  onChange={setPriority}
                  autoComplete="off"
                  helpText="Lower number = higher priority."
                />
              </div>
            </InlineStack>

            <TextField
              label="Specific Zip Codes (optional)"
              value={zipCodes}
              onChange={setZipCodes}
              placeholder="10001, 10002, 10003"
              autoComplete="off"
              helpText="Comma-separated zip codes. Leave empty to apply to all zip codes in the zone."
            />

            <Divider />
            <Text as="h3" variant="headingSm">
              Pricing
            </Text>

            <InlineStack gap="300">
              <div style={{ flex: 1 }}>
                <TextField
                  label="Delivery Fee ($)"
                  type="number"
                  value={deliveryFee}
                  onChange={setDeliveryFee}
                  placeholder="0.00"
                  autoComplete="off"
                  helpText="Leave empty for free delivery."
                />
              </div>
              <div style={{ flex: 1 }}>
                <TextField
                  label="Min. Order Amount ($)"
                  type="number"
                  value={minOrderAmount}
                  onChange={setMinOrderAmount}
                  placeholder="0.00"
                  autoComplete="off"
                  helpText="Minimum order to qualify for delivery."
                />
              </div>
            </InlineStack>

            <TextField
              label="Free Shipping Above ($)"
              type="number"
              value={freeShippingAbove}
              onChange={setFreeShippingAbove}
              placeholder="e.g. 50.00"
              autoComplete="off"
              helpText="Waive the delivery fee for orders above this amount."
            />

            <Divider />
            <Text as="h3" variant="headingSm">
              Schedule
            </Text>

            <InlineStack gap="300">
              <div style={{ flex: 1 }}>
                <TextField
                  label="Estimated Delivery"
                  value={estimatedDays}
                  onChange={setEstimatedDays}
                  placeholder="e.g. 2-3 days"
                  autoComplete="off"
                />
              </div>
              <div style={{ flex: 1 }}>
                <TextField
                  label="Order Cutoff Time"
                  value={cutoffTime}
                  onChange={setCutoffTime}
                  placeholder="e.g. 14:00"
                  autoComplete="off"
                  helpText="Orders after this time ship next delivery day."
                />
              </div>
            </InlineStack>

            <BlockStack gap="200">
              <Text as="p" variant="bodyMd">
                Delivery Days
              </Text>
              <InlineStack gap="300" wrap>
                {DAYS_OPTIONS.map((day) => (
                  <Checkbox
                    key={day.value}
                    label={day.label}
                    checked={selectedDays.includes(day.value)}
                    onChange={() => toggleDay(day.value)}
                  />
                ))}
              </InlineStack>
            </BlockStack>
          </BlockStack>
        </Modal.Section>
      </Modal>
    </Page>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

