              borderWidth="025"
              borderColor="border"
              borderRadius="200"
            >
              <BlockStack gap="100">
                <Text as="p" tone="subdued" variant="bodySm">
                  Unique Zips
                </Text>
                <Text as="p" variant="headingXl" fontWeight="bold">
                  {stats.uniqueZips}
                </Text>
              </BlockStack>
            </Box>
          </InlineGrid>
        </Layout.Section>

        {/* Waitlist Table */}
        <Layout.Section>
          <Card padding="0">
            <Box padding="400">
              <InlineStack
                gap="300"
                align="space-between"
                blockAlign="center"
                wrap
              >
                <InlineStack gap="300" blockAlign="center" wrap>
                  <div style={{ minWidth: "260px" }}>
                    <TextField
                      label="Search"
                      labelHidden
                      value={searchQuery}
                      onChange={handleSearchChange}
                      placeholder="Search by email or zip code..."
                      autoComplete="off"
                      prefix={<Icon source={SearchIcon} />}
                      clearButton
                      onClearButtonClick={() => handleSearchChange("")}
                    />
                  </div>
                  <div style={{ minWidth: "120px" }}>
                    <Select
                      label="Status"
                      labelHidden
                      options={filterOptions}
                      value={statusFilter}
                      onChange={handleFilterChange}
