        onClose={() => {
          setAddModalOpen(false);
          setNewEmail("");
          setNewZipCode("");
          setNewNote("");
        }}
        title="Add Waitlist Entry"
        primaryAction={{ content: "Add to Waitlist", onAction: handleAdd }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => {
              setAddModalOpen(false);
              setNewEmail("");
              setNewZipCode("");
              setNewNote("");
            },
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            {actionError && <Banner tone="critical">{actionError}</Banner>}
            <TextField
              label="Email"
              type="email"
              value={newEmail}
              onChange={setNewEmail}
              placeholder="customer@example.com"
              autoComplete="off"
            />
            <TextField
              label="Zip Code"
              value={newZipCode}
              onChange={setNewZipCode}
              placeholder="e.g. 33101"
              autoComplete="off"
            />
            <TextField
              label="Note (optional)"
              value={newNote}
              onChange={setNewNote}
              placeholder="Any additional notes..."
              autoComplete="off"
              multiline={2}
            />
