              autoComplete="off"
              helpText="Custom message shown to customers for this zip code."
            />
            <InlineStack gap="300">
              <div style={{ flex: 1 }}>
                <TextField
                  label="ETA"
                  value={newEta}
                  onChange={setNewEta}
                  placeholder="e.g. 2-3 days"
                  autoComplete="off"
                  helpText="Estimated delivery time."
                />
              </div>
              <div style={{ flex: 1 }}>
                <TextField
                  label="Label (optional)"
                  value={newLabel}
                  onChange={setNewLabel}
                  placeholder="e.g. Downtown LA"
                  autoComplete="off"
                  helpText="Internal label for your reference."
                />
              </div>
            </InlineStack>
            {isFreePlan && !limits.allowBlocked && (
              <Banner tone="info">
                <InlineStack gap="200" blockAlign="center">
                  <Text as="span" variant="bodySm">
                    Want to block zip codes?{" "}
                  </Text>
                  <Button
                    variant="plain"
                    onClick={() => {
                      setAddModalOpen(false);
                      navigate("/app/pricing");
                    }}
