          setNewNote("");
        }}
        title="Add Waitlist Entry"
        primaryAction={{ content: "Add to Waitlist", onAction: handleAdd }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => {
              setAddModalOpen(false);
              setNewEmail("");
              setNewZipCode("");
              setNewNote("");
            },
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            {actionError && <Banner tone="critical">{actionError}</Banner>}
            <TextField
              label="Email"
              type="email"
              value={newEmail}
              onChange={setNewEmail}
              placeholder="customer@example.com"
              autoComplete="off"
            />
            <TextField
              label="Zip Code"
              value={newZipCode}
              onChange={setNewZipCode}
              placeholder="e.g. 33101"
              autoComplete="off"
            />
            <TextField
              label="Note (optional)"
              value={newNote}
              onChange={setNewNote}
              placeholder="Any additional notes..."
              autoComplete="off"
              multiline={2}
            />
          </BlockStack>
        </Modal.Section>
      </Modal>

      {/* Bulk Notify Modal */}
      <Modal
        open={notifyModalOpen}
        onClose={() => {
          setNotifyModalOpen(false);
          setNotifyZip("");
        }}
        title="Notify Waitlist by Zip Code"
        primaryAction={{
          content: "Mark as Notified",
          onAction: handleBulkNotify,
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => {
              setNotifyModalOpen(false);
              setNotifyZip("");
            },
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            {bulkResult && (
              <Banner tone="success">
                Marked {bulkResult.count as number} customers as notified for
                zip code {bulkResult.zipCode as string}.
              </Banner>
            )}
            <Text as="p">
              Enter a zip code to mark all waiting customers for that area as
              &quot;Notified&quot;. Use this when you&apos;ve expanded delivery to a new area
              and want to let waitlisted customers know.
            </Text>
            <TextField
              label="Zip Code"
              value={notifyZip}
              onChange={setNotifyZip}
              placeholder="e.g. 33101"
              autoComplete="off"
            />
          </BlockStack>
        </Modal.Section>
      </Modal>
    </Page>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

