import { useState, useCallback } from "react";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import { useFetcher, useLoaderData, useNavigate } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  InlineGrid,
  Text,
  Button,
  TextField,
  Select,
  Checkbox,
  Divider,
  Box,
  Banner,
} from "@shopify/polaris";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  let config = await db.widgetConfig.findUnique({ where: { shop } });

  if (!config) {
    config = await db.widgetConfig.create({ data: { shop } });
  }

  return { config };
};

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent");

  if (intent === "save") {
    const data = {
      position: String(formData.get("position") || "inline"),
      primaryColor: String(formData.get("primaryColor") || "#008060"),
      successColor: String(formData.get("successColor") || "#008060"),
      errorColor: String(formData.get("errorColor") || "#D72C0D"),
      backgroundColor: String(formData.get("backgroundColor") || "#FFFFFF"),
      textColor: String(formData.get("textColor") || "#202223"),
      heading: String(formData.get("heading") || "Check Delivery Availability"),
      placeholder: String(formData.get("placeholder") || "Enter your zip code"),
      buttonText: String(formData.get("buttonText") || "Check"),
      successMessage: String(
        formData.get("successMessage") ||
          "Great news! We deliver to your area.",
      ),
      errorMessage: String(
        formData.get("errorMessage") ||
          "Sorry, we don't deliver to this area yet.",
      ),
      notFoundMessage: String(
        formData.get("notFoundMessage") ||
          "This zip code was not found in our system.",
      ),
      showEta: formData.get("showEta") === "true",
      showZone: formData.get("showZone") === "true",
      showWaitlistOnFailure: formData.get("showWaitlistOnFailure") === "true",
      borderRadius: String(formData.get("borderRadius") || "8"),
      customCss: String(formData.get("customCss") || "") || null,
    };

    await db.widgetConfig.upsert({
      where: { shop },
      create: { shop, ...data },
      update: data,
    });

    return { success: true };
  }

  if (intent === "reset") {
    await db.widgetConfig.upsert({
      where: { shop },
      create: { shop },
      update: {
        position: "inline",
        primaryColor: "#008060",
        successColor: "#008060",
        errorColor: "#D72C0D",
        backgroundColor: "#FFFFFF",
        textColor: "#202223",
        heading: "Check Delivery Availability",
        placeholder: "Enter your zip code",
        buttonText: "Check",
        successMessage: "Great news! We deliver to your area.",
        errorMessage: "Sorry, we don't deliver to this area yet.",
        notFoundMessage: "This zip code was not found in our system.",
        showEta: true,
        showZone: false,
        showWaitlistOnFailure: false,
        borderRadius: "8",
        customCss: null,
      },
    });
    return { success: true, action: "reset" };
  }

  return null;
};

type WidgetConfig = {
  position: string;
  primaryColor: string;
  successColor: string;
  errorColor: string;
  backgroundColor: string;
  textColor: string;
  heading: string;
  placeholder: string;
  buttonText: string;
  successMessage: string;
  errorMessage: string;
  notFoundMessage: string;
  showEta: boolean;
  showZone: boolean;
  showWaitlistOnFailure: boolean;
  borderRadius: string;
  customCss: string | null;
};

export default function WidgetPage() {
  const { config } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();
  const navigate = useNavigate();

  const c = config as WidgetConfig;

  // Form state initialized from DB
  const [position, setPosition] = useState(c.position);
  const [primaryColor, setPrimaryColor] = useState(c.primaryColor);
  const [successColor, setSuccessColor] = useState(c.successColor);
  const [errorColor, setErrorColor] = useState(c.errorColor);
  const [backgroundColor, setBackgroundColor] = useState(c.backgroundColor);
  const [textColor, setTextColor] = useState(c.textColor);
  const [heading, setHeading] = useState(c.heading);
  const [placeholder, setPlaceholder] = useState(c.placeholder);
  const [buttonText, setButtonText] = useState(c.buttonText);
  const [successMessage, setSuccessMessage] = useState(c.successMessage);
  const [errorMessage, setErrorMessage] = useState(c.errorMessage);
  const [notFoundMessage, setNotFoundMessage] = useState(c.notFoundMessage);
  const [showEta, setShowEta] = useState(c.showEta);
  const [showZone, setShowZone] = useState(c.showZone);
  const [showWaitlistOnFailure, setShowWaitlistOnFailure] = useState(
    c.showWaitlistOnFailure,
  );
  const [borderRadius, setBorderRadius] = useState(c.borderRadius);
  const [customCss, setCustomCss] = useState(c.customCss || "");

  // Preview state
  const [previewState, setPreviewState] = useState<
    "idle" | "success" | "error" | "notfound"
  >("idle");

  const isSaving =
    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "save";
  const saved =
    fetcher.data &&
    "success" in fetcher.data &&
    fetcher.data.success &&
    !("action" in fetcher.data);

  const handleSave = useCallback(() => {
    const fd = new FormData();
    fd.set("intent", "save");
    fd.set("position", position);
    fd.set("primaryColor", primaryColor);
    fd.set("successColor", successColor);
    fd.set("errorColor", errorColor);
    fd.set("backgroundColor", backgroundColor);
    fd.set("textColor", textColor);
    fd.set("heading", heading);
    fd.set("placeholder", placeholder);
    fd.set("buttonText", buttonText);
    fd.set("successMessage", successMessage);
    fd.set("errorMessage", errorMessage);
    fd.set("notFoundMessage", notFoundMessage);
    fd.set("showEta", String(showEta));
    fd.set("showZone", String(showZone));
    fd.set("showWaitlistOnFailure", String(showWaitlistOnFailure));
    fd.set("borderRadius", borderRadius);
    fd.set("customCss", customCss);
    fetcher.submit(fd, { method: "POST" });
    shopify.toast.show("Widget settings saved");
  }, [
    position,
    primaryColor,
    successColor,
    errorColor,
    backgroundColor,
    textColor,
    heading,
    placeholder,
    buttonText,
    successMessage,
    errorMessage,
    notFoundMessage,
    showEta,
    showZone,
    showWaitlistOnFailure,
    borderRadius,
    customCss,
    fetcher,
    shopify,
  ]);

  const handleReset = useCallback(() => {
    const fd = new FormData();
    fd.set("intent", "reset");
    fetcher.submit(fd, { method: "POST" });
    setPosition("inline");
    setPrimaryColor("#008060");
    setSuccessColor("#008060");
    setErrorColor("#D72C0D");
    setBackgroundColor("#FFFFFF");
    setTextColor("#202223");
    setHeading("Check Delivery Availability");
    setPlaceholder("Enter your zip code");
    setButtonText("Check");
    setSuccessMessage("Great news! We deliver to your area.");
    setErrorMessage("Sorry, we don't deliver to this area yet.");
    setNotFoundMessage("This zip code was not found in our system.");
    setShowEta(true);
    setShowZone(false);
    setShowWaitlistOnFailure(false);
    setBorderRadius("8");
    setCustomCss("");
    setPreviewState("idle");
    shopify.toast.show("Widget settings reset to defaults");
  }, [fetcher, shopify]);

  const positionOptions = [
    { label: "Inline (embedded in page)", value: "inline" },
    { label: "Floating button", value: "floating" },
    { label: "Popup modal", value: "popup" },
  ];

  // Live preview widget
  const WidgetPreview = () => {
    const rad = `${borderRadius}px`;

    const resultMessage =
      previewState === "success"
        ? successMessage
        : previewState === "error"
          ? errorMessage
          : previewState === "notfound"
            ? notFoundMessage
            : null;

    const resultColor =
      previewState === "success"
        ? successColor
        : previewState === "error" || previewState === "notfound"
          ? errorColor
          : "transparent";

    return (
      <div
        style={{
          backgroundColor,
          color: textColor,
          borderRadius: rad,
          padding: "24px",
          border: "1px solid #e1e3e5",
          fontFamily:
            '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
          maxWidth: "400px",
        }}
      >
        <div
          style={{
            fontSize: "16px",
            fontWeight: 600,
            marginBottom: "16px",
            color: textColor,
          }}
        >
          {heading}
        </div>
        <div style={{ display: "flex", gap: "8px", marginBottom: "12px" }}>
          <input
            type="text"
            placeholder={placeholder}
            readOnly
            style={{
              flex: 1,
              padding: "10px 12px",
              border: "1px solid #c9cccf",
              borderRadius: rad,
              fontSize: "14px",
              outline: "none",
              color: textColor,
              backgroundColor: "#fafbfb",
            }}
          />
          <button
            type="button"
            style={{
              backgroundColor: primaryColor,
              color: "#fff",
              border: "none",
              borderRadius: rad,
              padding: "10px 20px",
              fontSize: "14px",
              fontWeight: 600,
              cursor: "pointer",
            }}
          >
            {buttonText}
          </button>
        </div>

        {resultMessage && (
          <div
            style={{
              padding: "12px",
              borderRadius: rad,
              backgroundColor: `${resultColor}15`,
              borderLeft: `3px solid ${resultColor}`,
              fontSize: "14px",
              color: resultColor,
            }}
          >
            {resultMessage}
            {previewState === "success" && showEta && (
              <div
                style={{
                  marginTop: "4px",
                  fontSize: "13px",
                  opacity: 0.8,
                }}
              >
                Estimated delivery: 2-3 days
              </div>
            )}
            {previewState === "success" && showZone && (
              <div
                style={{
                  marginTop: "4px",
                  fontSize: "13px",
                  opacity: 0.8,
                }}
              >
                Zone: Manhattan
              </div>
            )}
            {(previewState === "error" || previewState === "notfound") &&
              showWaitlistOnFailure && (
                <div style={{ marginTop: "8px" }}>
                  <input
                    type="email"
                    placeholder="Enter your email to join waitlist"
                    readOnly
                    style={{
                      width: "100%",
                      padding: "8px 10px",
                      border: `1px solid ${errorColor}40`,
                      borderRadius: rad,
                      fontSize: "13px",
                      boxSizing: "border-box",
                    }}
                  />
                </div>
              )}
          </div>
        )}
      </div>
    );
  };

  return (
    <Page
      title="Widget Customization"
      subtitle="Customize how the zip code checker looks on your storefront"
      backAction={{ onAction: () => navigate("/app") }}
      primaryAction={{
        content: "Save Changes",
        onAction: handleSave,
        loading: isSaving,
      }}
      secondaryActions={[
        {
          content: "Reset to Defaults",
          onAction: handleReset,
          destructive: true,
        },
      ]}
    >
      <Box paddingBlockEnd="1600">
      <Layout>
        {saved && (
          <Layout.Section>
            <Banner tone="success" title="Settings saved successfully" />
          </Layout.Section>
        )}

        <Layout.Section>
          <InlineGrid columns={{ xs: 1, md: 2 }} gap="400">
            {/* Settings Column */}
            <BlockStack gap="400">
                {/* Layout */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd">
                      Layout
                    </Text>
                    <Select
                      label="Widget Position"
                      options={positionOptions}
                      value={position}
                      onChange={setPosition}
                    />
                    <TextField
                      label="Border Radius (px)"
                      type="number"
                      value={borderRadius}
                      onChange={setBorderRadius}
                      autoComplete="off"
                      helpText="Roundness of corners. 0 = square, 16 = very rounded."
                    />
                  </BlockStack>
                </Card>

                {/* Colors */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd">
                      Colors
                    </Text>
                    <InlineStack gap="300" wrap>
                      <div style={{ flex: 1, minWidth: "140px" }}>
                        <BlockStack gap="100">
                          <Text as="p" variant="bodySm">
                            Button Color
                          </Text>
                          <InlineStack gap="200" blockAlign="center">
                            <input
                              type="color"
                              value={primaryColor}
                              onChange={(e) => setPrimaryColor(e.target.value)}
                              style={{
                                width: "36px",
                                height: "36px",
                                border: "1px solid #ccc",
                                borderRadius: "6px",
                                cursor: "pointer",
                                padding: "2px",
                              }}
                            />
                            <TextField
                              label="Button"
                              labelHidden
                              value={primaryColor}
                              onChange={setPrimaryColor}
                              autoComplete="off"
                            />
                          </InlineStack>
                        </BlockStack>
                      </div>
                      <div style={{ flex: 1, minWidth: "140px" }}>
                        <BlockStack gap="100">
                          <Text as="p" variant="bodySm">
                            Success Color
                          </Text>
                          <InlineStack gap="200" blockAlign="center">
                            <input
                              type="color"
                              value={successColor}
                              onChange={(e) => setSuccessColor(e.target.value)}
                              style={{
                                width: "36px",
                                height: "36px",
                                border: "1px solid #ccc",
                                borderRadius: "6px",
                                cursor: "pointer",
                                padding: "2px",
                              }}
                            />
                            <TextField
                              label="Success"
                              labelHidden
                              value={successColor}
                              onChange={setSuccessColor}
                              autoComplete="off"
                            />
                          </InlineStack>
                        </BlockStack>
                      </div>
                    </InlineStack>
                    <InlineStack gap="300" wrap>
                      <div style={{ flex: 1, minWidth: "140px" }}>
                        <BlockStack gap="100">
                          <Text as="p" variant="bodySm">
                            Error Color
                          </Text>
                          <InlineStack gap="200" blockAlign="center">
                            <input
                              type="color"
                              value={errorColor}
                              onChange={(e) => setErrorColor(e.target.value)}
                              style={{
                                width: "36px",
                                height: "36px",
                                border: "1px solid #ccc",
                                borderRadius: "6px",
                                cursor: "pointer",
                                padding: "2px",
                              }}
                            />
                            <TextField
                              label="Error"
                              labelHidden
                              value={errorColor}
                              onChange={setErrorColor}
                              autoComplete="off"
                            />
                          </InlineStack>
                        </BlockStack>
                      </div>
                      <div style={{ flex: 1, minWidth: "140px" }}>
                        <BlockStack gap="100">
                          <Text as="p" variant="bodySm">
                            Background
                          </Text>
                          <InlineStack gap="200" blockAlign="center">
                            <input
                              type="color"
                              value={backgroundColor}
                              onChange={(e) =>
                                setBackgroundColor(e.target.value)
                              }
                              style={{
                                width: "36px",
                                height: "36px",
                                border: "1px solid #ccc",
                                borderRadius: "6px",
                                cursor: "pointer",
                                padding: "2px",
                              }}
                            />
                            <TextField
                              label="BG"
                              labelHidden
                              value={backgroundColor}
                              onChange={setBackgroundColor}
                              autoComplete="off"
                            />
                          </InlineStack>
                        </BlockStack>
                      </div>
                    </InlineStack>
                    <BlockStack gap="100">
                      <Text as="p" variant="bodySm">
                        Text Color
                      </Text>
                      <InlineStack gap="200" blockAlign="center">
                        <input
                          type="color"
                          value={textColor}
                          onChange={(e) => setTextColor(e.target.value)}
                          style={{
                            width: "36px",
                            height: "36px",
                            border: "1px solid #ccc",
                            borderRadius: "6px",
                            cursor: "pointer",
                            padding: "2px",
                          }}
                        />
                        <TextField
                          label="Text"
                          labelHidden
                          value={textColor}
                          onChange={setTextColor}
                          autoComplete="off"
                        />
                      </InlineStack>
                    </BlockStack>
                  </BlockStack>
                </Card>

                {/* Text Content */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd">
                      Text Content
                    </Text>
                    <TextField
                      label="Heading"
                      value={heading}
                      onChange={setHeading}
                      autoComplete="off"
                    />
                    <InlineStack gap="300">
                      <div style={{ flex: 1 }}>
                        <TextField
                          label="Placeholder"
                          value={placeholder}
                          onChange={setPlaceholder}
                          autoComplete="off"
                        />
                      </div>
                      <div style={{ flex: 1 }}>
                        <TextField
                          label="Button Text"
                          value={buttonText}
                          onChange={setButtonText}
                          autoComplete="off"
                        />
                      </div>
                    </InlineStack>
                    <TextField
                      label="Success Message"
                      value={successMessage}
                      onChange={setSuccessMessage}
                      autoComplete="off"
                      multiline={2}
