/**
 * Public API endpoint — joins a customer to the waitlist from the storefront widget.
 *
 * Called from the theme app extension block when a zip code check fails and
 * the merchant has enabled the waitlist feature.
 *
 * POST /api/waitlist
 * Body: { shop: string, zip: string, email: string }
 *
 * Response:
 *   200 { success: true, message: "..." }
 *   400 { error: "..." }
 *   500 { error: "..." }
 */
import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
import db from "../db.server";

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
  "Content-Type": "application/json",
};

// Handle CORS preflight
export const loader = async ({ request }: LoaderFunctionArgs) => {
  if (request.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }
  return new Response(JSON.stringify({ error: "Method not allowed" }), {
    status: 405,
    headers: CORS_HEADERS,
  });
};

export const action = async ({ request }: ActionFunctionArgs) => {
  if (request.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }

  if (request.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405,
      headers: CORS_HEADERS,
    });
  }

  let shop: string | null = null;
  let zip: string | null = null;
  let email: string | null = null;

  try {
    const body = await request.json();
    shop = body?.shop ?? null;
    zip = body?.zip ?? null;
    email = body?.email ?? null;
  } catch {
    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
      status: 400,
      headers: CORS_HEADERS,
    });
  }

  if (!shop || !zip || !email) {
    return new Response(
      JSON.stringify({ error: "Missing required fields: shop, zip, email" }),
      { status: 400, headers: CORS_HEADERS },
    );
  }

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return new Response(
      JSON.stringify({ error: "Invalid email address" }),
      { status: 400, headers: CORS_HEADERS },
    );
  }

  try {
    await db.waitlistEntry.upsert({
      where: {
        shop_email_zipCode: {
          shop,
          email,
          zipCode: zip.trim().toUpperCase(),
        },
      },
      create: {
        shop,
        email,
        zipCode: zip.trim().toUpperCase(),
        status: "waiting",
      },
      update: {
        status: "waiting",
      },
    });

    return new Response(
      JSON.stringify({
        success: true,
        message: "You've been added to the waitlist!",
      }),
      { status: 200, headers: CORS_HEADERS },
    );
  } catch {
    return new Response(
      JSON.stringify({ error: "Failed to join waitlist. Please try again." }),
      { status: 500, headers: CORS_HEADERS },
    );
  }
};

