        "max-width:480px;" +
        "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;" +
        "box-sizing:border-box;" +
      "}" +
      "#" + WID + " *{box-sizing:border-box}" +
      "#" + WID + " .zcc-heading{font-size:16px;font-weight:600;margin:0 0 16px;color:" + cfg.textColor + "}" +
      "#" + WID + " .zcc-row{display:flex;gap:8px;margin-bottom:0}" +
      "#" + WID + " .zcc-input{" +
        "flex:1;padding:10px 12px;border:1px solid #c9cccf;" +
        "border-radius:" + rad + ";font-size:14px;outline:none;" +
        "background:#fafbfb;color:" + cfg.textColor + ";min-width:0" +
      "}" +
      "#" + WID + " .zcc-input:focus{border-color:" + cfg.primaryColor + ";box-shadow:0 0 0 2px " + cfg.primaryColor + "22}" +
      "#" + WID + " .zcc-btn{" +
        "background:" + cfg.primaryColor + ";color:#fff;border:none;" +
        "border-radius:" + rad + ";padding:10px 20px;font-size:14px;" +
        "font-weight:600;cursor:pointer;white-space:nowrap;flex-shrink:0" +
      "}" +
      "#" + WID + " .zcc-btn:hover{opacity:.9}" +
      "#" + WID + " .zcc-btn:disabled{opacity:.6;cursor:not-allowed}" +
      "#" + WID + " .zcc-result{margin-top:12px;padding:12px;border-radius:" + rad + ";font-size:14px;line-height:1.4}" +
      "#" + WID + " .zcc-result.ok{background:" + cfg.successColor + "15;border-left:3px solid " + cfg.successColor + ";color:" + cfg.successColor + "}" +
      "#" + WID + " .zcc-result.fail{background:" + cfg.errorColor + "15;border-left:3px solid " + cfg.errorColor + ";color:" + cfg.errorColor + "}" +
      "#" + WID + " .zcc-meta{margin-top:4px;font-size:13px;opacity:.8}" +
      "#" + WID + " .zcc-wl{margin-top:10px}" +
      "#" + WID + " .zcc-wl-input{" +
        "width:100%;padding:8px 10px;border:1px solid " + cfg.errorColor + "40;" +
        "border-radius:" + rad + ";font-size:13px;margin-bottom:6px;display:block" +
      "}" +
      "#" + WID + " .zcc-wl-btn{" +
        "background:" + cfg.errorColor + ";color:#fff;border:none;" +
        "border-radius:" + rad + ";padding:8px 16px;font-size:13px;" +
        "cursor:pointer;width:100%;font-weight:600" +
      "}" +
      "#" + WID + " .zcc-wl-btn:disabled{opacity:.6;cursor:not-allowed}" +
      (cfg.customCss || "");

    var styleEl = document.createElement("style");
    styleEl.textContent = css;
    document.head.appendChild(styleEl);

    // ---- Build HTML ----
    container.id = WID;
    container.innerHTML =
      '<p class="zcc-heading">' + esc(cfg.heading) + "</p>" +
      '<div class="zcc-row">' +
        '<input class="zcc-input" type="text" id="' + WID + '-inp"' +
          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
        '<button class="zcc-btn" id="' + WID + '-btn" type="button">' + esc(cfg.buttonText) + "</button>" +
      "</div>" +
      '<div id="' + WID + '-res"></div>';

    var inp = document.getElementById(WID + "-inp");
    var btn = document.getElementById(WID + "-btn");
    var res = document.getElementById(WID + "-res");
    var btnLabel = cfg.buttonText;

    function checkZip() {
      var zip = inp.value.trim();
      if (!zip) { inp.focus(); return; }

      btn.disabled = true;
      btn.textContent = "\u2026";
      res.innerHTML = "";

      fetch(
        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
          "&zip=" + encodeURIComponent(zip)
      )
        .then(function (r) { return r.json(); })
        .then(function (data) {
          btn.disabled = false;
          btn.textContent = btnLabel;

          if (data.allowed) {
            var html = '<div class="zcc-result ok">' + esc(data.message);
            if (cfg.showEta && data.eta) {
              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
            }
            if (cfg.showZone && data.zone) {
              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
            }
            html += "</div>";
            res.innerHTML = html;
          } else {
            var html = '<div class="zcc-result fail">' + esc(data.message);
            if (cfg.showWaitlistOnFailure) {
              html +=
                '<div class="zcc-wl">' +
                '<input class="zcc-wl-input" type="email" id="' + WID + '-wl-email" placeholder="Enter email to join waitlist" />' +
                '<button class="zcc-wl-btn" id="' + WID + '-wl-btn" type="button">Join Waitlist</button>' +
                "</div>";
            }
            html += "</div>";
            res.innerHTML = html;

            if (cfg.showWaitlistOnFailure) {
              var wBtn = document.getElementById(WID + "-wl-btn");
              if (wBtn) {
                wBtn.addEventListener("click", function () {
                  var emailEl = document.getElementById(WID + "-wl-email");
                  var email = emailEl ? emailEl.value.trim() : "";
                  if (!email) { if (emailEl) emailEl.focus(); return; }
                  joinWaitlist(zip, email, wBtn);
                });
              }
            }
          }
        })
        .catch(function () {
          btn.disabled = false;
          btn.textContent = btnLabel;
          res.innerHTML = '<div class="zcc-result fail">Something went wrong. Please try again.</div>';
        });
    }

    function joinWaitlist(zip, email, wBtn) {
      wBtn.disabled = true;
      wBtn.textContent = "Joining\u2026";

      fetch(API_BASE + "/api/waitlist", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ shop: SHOP, zip: zip, email: email }),
      })
        .then(function (r) { return r.json(); })
        .then(function (data) {
          var wlEl = wBtn.closest(".zcc-wl");
          if (data.success) {
            if (wlEl) wlEl.innerHTML =
              '<p style="font-size:13px;margin:6px 0 0">' +
              "\u2713 You\u2019ve been added to the waitlist!" +
              "</p>";
          } else {
            wBtn.disabled = false;
            wBtn.textContent = "Join Waitlist";
          }
        })
        .catch(function () {
          wBtn.disabled = false;
          wBtn.textContent = "Join Waitlist";
        });
    }

    btn.addEventListener("click", checkZip);
    inp.addEventListener("keydown", function (e) {
      if (e.key === "Enter") checkZip();
    });
  }

  function esc(str) {
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function escAttr(str) {
    return String(str).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
  }
})();
</script>

