            </BlockStack>
          </Card>
        </Layout.Section>

        <Layout.Section>
          <InlineGrid columns={{ xs: 1, md: 2 }} gap="400">
            {/* Settings Column */}
            <BlockStack gap="400">
                {/* Layout */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd">
