import { useState, useCallback } from "react";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import { useFetcher, useLoaderData, useNavigate } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  InlineGrid,
  Text,
  Button,
  TextField,
  Select,
  Checkbox,
  Divider,
  Box,
  Banner,
} from "@shopify/polaris";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  let config = await db.widgetConfig.findUnique({ where: { shop } });

  if (!config) {
    config = await db.widgetConfig.create({ data: { shop } });
  }

  const themeEditorUrl = `https://${shop}/admin/themes/current/editor`;

  return { config, themeEditorUrl };
};

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent");

  if (intent === "save") {
    const data = {
      position: String(formData.get("position") || "inline"),
      primaryColor: String(formData.get("primaryColor") || "#008060"),
      successColor: String(formData.get("successColor") || "#008060"),
      errorColor: String(formData.get("errorColor") || "#D72C0D"),
      backgroundColor: String(formData.get("backgroundColor") || "#FFFFFF"),
      textColor: String(formData.get("textColor") || "#202223"),
      heading: String(formData.get("heading") || "Check Delivery Availability"),
      placeholder: String(formData.get("placeholder") || "Enter your zip code"),
      buttonText: String(formData.get("buttonText") || "Check"),
      successMessage: String(
        formData.get("successMessage") ||
          "Great news! We deliver to your area.",
      ),
      errorMessage: String(
        formData.get("errorMessage") ||
          "Sorry, we don't deliver to this area yet.",
      ),
      notFoundMessage: String(
        formData.get("notFoundMessage") ||
          "This zip code was not found in our system.",
      ),
      showEta: formData.get("showEta") === "true",
      showZone: formData.get("showZone") === "true",
      showWaitlistOnFailure: formData.get("showWaitlistOnFailure") === "true",
      borderRadius: String(formData.get("borderRadius") || "8"),
      customCss: String(formData.get("customCss") || "") || null,
    };

    await db.widgetConfig.upsert({
      where: { shop },
      create: { shop, ...data },
      update: data,
    });

    return { success: true };
  }

  if (intent === "reset") {
    await db.widgetConfig.upsert({
      where: { shop },
      create: { shop },
      update: {
        position: "inline",
        primaryColor: "#008060",
        successColor: "#008060",
        errorColor: "#D72C0D",
        backgroundColor: "#FFFFFF",
        textColor: "#202223",
        heading: "Check Delivery Availability",
        placeholder: "Enter your zip code",
        buttonText: "Check",
        successMessage: "Great news! We deliver to your area.",
        errorMessage: "Sorry, we don't deliver to this area yet.",
        notFoundMessage: "This zip code was not found in our system.",
        showEta: true,
        showZone: false,
        showWaitlistOnFailure: false,
        borderRadius: "8",
        customCss: null,
      },
    });
    return { success: true, action: "reset" };
  }

  return null;
};

type WidgetConfig = {
  position: string;
  primaryColor: string;
  successColor: string;
  errorColor: string;
  backgroundColor: string;
  textColor: string;
  heading: string;
  placeholder: string;
  buttonText: string;
  successMessage: string;
  errorMessage: string;
  notFoundMessage: string;
  showEta: boolean;
  showZone: boolean;
  showWaitlistOnFailure: boolean;
  borderRadius: string;
  customCss: string | null;
};

export default function WidgetPage() {
  const { config, themeEditorUrl } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();
  const navigate = useNavigate();

  const c = config as WidgetConfig;

  // Form state initialized from DB
  const [position, setPosition] = useState(c.position);
  const [primaryColor, setPrimaryColor] = useState(c.primaryColor);
  const [successColor, setSuccessColor] = useState(c.successColor);
  const [errorColor, setErrorColor] = useState(c.errorColor);
  const [backgroundColor, setBackgroundColor] = useState(c.backgroundColor);
  const [textColor, setTextColor] = useState(c.textColor);
  const [heading, setHeading] = useState(c.heading);
  const [placeholder, setPlaceholder] = useState(c.placeholder);
  const [buttonText, setButtonText] = useState(c.buttonText);
  const [successMessage, setSuccessMessage] = useState(c.successMessage);
  const [errorMessage, setErrorMessage] = useState(c.errorMessage);
  const [notFoundMessage, setNotFoundMessage] = useState(c.notFoundMessage);
  const [showEta, setShowEta] = useState(c.showEta);
  const [showZone, setShowZone] = useState(c.showZone);
  const [showWaitlistOnFailure, setShowWaitlistOnFailure] = useState(
    c.showWaitlistOnFailure,
  );
  const [borderRadius, setBorderRadius] = useState(c.borderRadius);
  const [customCss, setCustomCss] = useState(c.customCss || "");

  // Preview state
  const [previewState, setPreviewState] = useState<
    "idle" | "success" | "error" | "notfound"
  >("idle");

  const isSaving =
    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "save";
  const saved =
    fetcher.data &&
    "success" in fetcher.data &&
    fetcher.data.success &&
    !("action" in fetcher.data);

  const handleSave = useCallback(() => {
    const fd = new FormData();
    fd.set("intent", "save");
    fd.set("position", position);
    fd.set("primaryColor", primaryColor);
    fd.set("successColor", successColor);
    fd.set("errorColor", errorColor);
    fd.set("backgroundColor", backgroundColor);
    fd.set("textColor", textColor);
    fd.set("heading", heading);
    fd.set("placeholder", placeholder);
    fd.set("buttonText", buttonText);
    fd.set("successMessage", successMessage);
    fd.set("errorMessage", errorMessage);
    fd.set("notFoundMessage", notFoundMessage);
    fd.set("showEta", String(showEta));
    fd.set("showZone", String(showZone));
    fd.set("showWaitlistOnFailure", String(showWaitlistOnFailure));
    fd.set("borderRadius", borderRadius);
    fd.set("customCss", customCss);
    fetcher.submit(fd, { method: "POST" });
    shopify.toast.show("Widget settings saved");
  }, [
    position,
    primaryColor,
    successColor,
    errorColor,
    backgroundColor,
    textColor,
    heading,
    placeholder,
    buttonText,
    successMessage,
    errorMessage,
    notFoundMessage,
    showEta,
    showZone,
    showWaitlistOnFailure,
    borderRadius,
    customCss,
    fetcher,
    shopify,
  ]);

  const handleReset = useCallback(() => {
    const fd = new FormData();
    fd.set("intent", "reset");
    fetcher.submit(fd, { method: "POST" });
    setPosition("inline");
    setPrimaryColor("#008060");
    setSuccessColor("#008060");
    setErrorColor("#D72C0D");
    setBackgroundColor("#FFFFFF");
    setTextColor("#202223");
    setHeading("Check Delivery Availability");
    setPlaceholder("Enter your zip code");
    setButtonText("Check");
    setSuccessMessage("Great news! We deliver to your area.");
    setErrorMessage("Sorry, we don't deliver to this area yet.");
    setNotFoundMessage("This zip code was not found in our system.");
    setShowEta(true);
    setShowZone(false);
    setShowWaitlistOnFailure(false);
    setBorderRadius("8");
    setCustomCss("");
    setPreviewState("idle");
    shopify.toast.show("Widget settings reset to defaults");
  }, [fetcher, shopify]);

  const positionOptions = [
    { label: "Inline (embedded in page)", value: "inline" },
    { label: "Floating button", value: "floating" },
    { label: "Popup modal", value: "popup" },
  ];

  // Live preview widget
  const WidgetPreview = () => {
    const rad = `${borderRadius}px`;

    const resultMessage =
      previewState === "success"
        ? successMessage
        : previewState === "error"
          ? errorMessage
          : previewState === "notfound"
            ? notFoundMessage
            : null;

    const resultColor =
      previewState === "success"
        ? successColor
        : previewState === "error" || previewState === "notfound"
          ? errorColor
          : "transparent";

    return (
      <div
        style={{
          backgroundColor,
          color: textColor,
          borderRadius: rad,
          padding: "24px",
          border: "1px solid #e1e3e5",
          fontFamily:
            '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
          maxWidth: "400px",
        }}
      >
        <div
          style={{
            fontSize: "16px",
            fontWeight: 600,
            marginBottom: "16px",
            color: textColor,
          }}
        >
          {heading}
        </div>
        <div style={{ display: "flex", gap: "8px", marginBottom: "12px" }}>
          <input
            type="text"
            placeholder={placeholder}
            readOnly
            style={{
              flex: 1,
              padding: "10px 12px",
              border: "1px solid #c9cccf",
              borderRadius: rad,
              fontSize: "14px",
              outline: "none",
              color: textColor,
              backgroundColor: "#fafbfb",
            }}
          />
          <button
            type="button"
            style={{
              backgroundColor: primaryColor,
              color: "#fff",
              border: "none",
              borderRadius: rad,
              padding: "10px 20px",
              fontSize: "14px",
              fontWeight: 600,
              cursor: "pointer",
            }}
          >
            {buttonText}
          </button>
        </div>

        {resultMessage && (
          <div
            style={{
              padding: "12px",
              borderRadius: rad,
              backgroundColor: `${resultColor}15`,
              borderLeft: `3px solid ${resultColor}`,
              fontSize: "14px",
              color: resultColor,
            }}
          >
            {resultMessage}
            {previewState === "success" && showEta && (
              <div
                style={{
                  marginTop: "4px",
                  fontSize: "13px",
                  opacity: 0.8,
                }}
              >
                Estimated delivery: 2-3 days
              </div>
            )}
            {previewState === "success" && showZone && (
              <div
                style={{
                  marginTop: "4px",
                  fontSize: "13px",
                  opacity: 0.8,
                }}
              >
                Zone: Manhattan
              </div>
            )}
            {(previewState === "error" || previewState === "notfound") &&
              showWaitlistOnFailure && (
                <div style={{ marginTop: "8px" }}>
                  <input
                    type="email"
                    placeholder="Enter your email to join waitlist"
                    readOnly
                    style={{
                      width: "100%",
                      padding: "8px 10px",
                      border: `1px solid ${errorColor}40`,
                      borderRadius: rad,
                      fontSize: "13px",
                      boxSizing: "border-box",
                    }}
                  />
                </div>
              )}
          </div>
        )}
      </div>
    );
  };

  return (
    <Page
      title="Widget Customization"
      subtitle="Customize how the zip code checker looks on your storefront"
      backAction={{ onAction: () => navigate("/app") }}
      primaryAction={{
        content: "Save Changes",
        onAction: handleSave,
        loading: isSaving,
      }}
      secondaryActions={[
        {
          content: "Reset to Defaults",
          onAction: handleReset,
          destructive: true,
        },
      ]}
    >
      <Box paddingBlockEnd="1600">
      <Layout>
        {saved && (
          <Layout.Section>
            <Banner tone="success" title="Settings saved successfully" />
          </Layout.Section>
        )}

        <Layout.Section>
          <Card>
            <BlockStack gap="400">
              <BlockStack gap="100">
                <Text as="h2" variant="headingMd">
                  Add widget to your storefront
                </Text>
                <Text as="p" variant="bodySm" tone="subdued">
                  Follow these steps to display the zip code checker on your
                  online store. No manual URL configuration required.
                </Text>
              </BlockStack>
              <Divider />
              <BlockStack gap="300">
                <Text as="p" variant="bodyMd">
                  <strong>Step 1 —</strong> Save your widget settings using the{" "}
                  <strong>Save Changes</strong> button above
                </Text>
                <Text as="p" variant="bodyMd">
                  <strong>Step 2 —</strong> Open the Theme Editor, navigate to
                  a <strong>Product</strong> page template, click{" "}
                  <strong>Add block</strong> in any section, and select{" "}
                  <strong>Zip Code Checker</strong> under <strong>Apps</strong>
                </Text>
                <div>
                  <Button
                    url={`${themeEditorUrl}?template=product`}
                    target="_blank"
                    variant="primary"
                  >
                    Open Theme Editor
                  </Button>
                </div>
                <Text as="p" variant="bodyMd">
                  <strong>Step 3 —</strong> Click <strong>Save</strong> in the
                  Theme Editor — the widget connects automatically, no URL
                  configuration needed
                </Text>
              </BlockStack>
            </BlockStack>
          </Card>
        </Layout.Section>

        <Layout.Section>
          <InlineGrid columns={{ xs: 1, md: 2 }} gap="400">
            {/* Settings Column */}
            <BlockStack gap="400">
                {/* Layout */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd">
                      Layout
                    </Text>
                    <Select
                      label="Widget Position"
                      options={positionOptions}
                      value={position}
                      onChange={setPosition}
                    />
                    <TextField
                      label="Border Radius (px)"
                      type="number"
                      value={borderRadius}
                      onChange={setBorderRadius}
                      autoComplete="off"
                      helpText="Roundness of corners. 0 = square, 16 = very rounded."
                    />
                  </BlockStack>
                </Card>

                {/* Colors */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd">
                      Colors
                    </Text>
                    <InlineStack gap="300" wrap>
                      <div style={{ flex: 1, minWidth: "140px" }}>
                        <BlockStack gap="100">
                          <Text as="p" variant="bodySm">
                            Button Color
                          </Text>
                          <InlineStack gap="200" blockAlign="center">
                            <input
                              type="color"
                              value={primaryColor}
                              onChange={(e) => setPrimaryColor(e.target.value)}
                              style={{
                                width: "36px",
                                height: "36px",
                                border: "1px solid #ccc",
                                borderRadius: "6px",
                                cursor: "pointer",
                                padding: "2px",
                              }}
                            />
                            <TextField
                              label="Button"
                              labelHidden
                              value={primaryColor}
                              onChange={setPrimaryColor}
                              autoComplete="off"
                            />
                          </InlineStack>
                        </BlockStack>
                      </div>
                      <div style={{ flex: 1, minWidth: "140px" }}>
                        <BlockStack gap="100">
                          <Text as="p" variant="bodySm">
                            Success Color
                          </Text>
                          <InlineStack gap="200" blockAlign="center">
                            <input
                              type="color"
                              value={successColor}
                              onChange={(e) => setSuccessColor(e.target.value)}
                              style={{
                                width: "36px",
                                height: "36px",
                                border: "1px solid #ccc",
                                borderRadius: "6px",
                                cursor: "pointer",
                                padding: "2px",
                              }}
                            />
                            <TextField
                              label="Success"
                              labelHidden
                              value={successColor}
                              onChange={setSuccessColor}
                              autoComplete="off"
                            />
                          </InlineStack>
                        </BlockStack>
                      </div>
                    </InlineStack>
                    <InlineStack gap="300" wrap>
                      <div style={{ flex: 1, minWidth: "140px" }}>
                        <BlockStack gap="100">
                          <Text as="p" variant="bodySm">
                            Error Color
                          </Text>
                          <InlineStack gap="200" blockAlign="center">
                            <input
                              type="color"
                              value={errorColor}
                              onChange={(e) => setErrorColor(e.target.value)}
                              style={{
                                width: "36px",
                                height: "36px",
                                border: "1px solid #ccc",
                                borderRadius: "6px",
                                cursor: "pointer",
                                padding: "2px",
                              }}
                            />
                            <TextField
                              label="Error"
                              labelHidden
                              value={errorColor}
                              onChange={setErrorColor}
                              autoComplete="off"
                            />
                          </InlineStack>
                        </BlockStack>
                      </div>
                      <div style={{ flex: 1, minWidth: "140px" }}>
                        <BlockStack gap="100">
                          <Text as="p" variant="bodySm">
                            Background
                          </Text>
                          <InlineStack gap="200" blockAlign="center">
                            <input
                              type="color"
                              value={backgroundColor}
                              onChange={(e) =>
                                setBackgroundColor(e.target.value)
                              }
                              style={{
                                width: "36px",
                                height: "36px",
                                border: "1px solid #ccc",
                                borderRadius: "6px",
                                cursor: "pointer",
                                padding: "2px",
                              }}
                            />
                            <TextField
                              label="BG"
                              labelHidden
                              value={backgroundColor}
                              onChange={setBackgroundColor}
                              autoComplete="off"
                            />
                          </InlineStack>
                        </BlockStack>
                      </div>
                    </InlineStack>
                    <BlockStack gap="100">
                      <Text as="p" variant="bodySm">
                        Text Color
                      </Text>
                      <InlineStack gap="200" blockAlign="center">
                        <input
                          type="color"
                          value={textColor}
                          onChange={(e) => setTextColor(e.target.value)}
                          style={{
                            width: "36px",
                            height: "36px",
                            border: "1px solid #ccc",
                            borderRadius: "6px",
                            cursor: "pointer",
                            padding: "2px",
                          }}
                        />
                        <TextField
                          label="Text"
                          labelHidden
                          value={textColor}
                          onChange={setTextColor}
                          autoComplete="off"
                        />
                      </InlineStack>
                    </BlockStack>
                  </BlockStack>
                </Card>

                {/* Text Content */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd">
                      Text Content
                    </Text>
                    <TextField
                      label="Heading"
                      value={heading}
                      onChange={setHeading}
                      autoComplete="off"
                    />
                    <InlineStack gap="300">
                      <div style={{ flex: 1 }}>
                        <TextField
                          label="Placeholder"
                          value={placeholder}
                          onChange={setPlaceholder}
                          autoComplete="off"
                        />
                      </div>
                      <div style={{ flex: 1 }}>
                        <TextField
                          label="Button Text"
                          value={buttonText}
                          onChange={setButtonText}
                          autoComplete="off"
                        />
                      </div>
                    </InlineStack>
                    <TextField
                      label="Success Message"
                      value={successMessage}
                      onChange={setSuccessMessage}
                      autoComplete="off"
                      multiline={2}
                    />
                    <TextField
                      label="Error Message (blocked)"
                      value={errorMessage}
                      onChange={setErrorMessage}
                      autoComplete="off"
                      multiline={2}
                    />
                    <TextField
                      label="Not Found Message"
                      value={notFoundMessage}
                      onChange={setNotFoundMessage}
                      autoComplete="off"
                      multiline={2}
                    />
                  </BlockStack>
                </Card>

                {/* Features */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd">
                      Display Options
                    </Text>
                    <Checkbox
                      label="Show estimated delivery time (ETA)"
                      checked={showEta}
                      onChange={setShowEta}
                      helpText="Display the ETA below the success message when available."
                    />
                    <Checkbox
                      label="Show delivery zone name"
                      checked={showZone}
                      onChange={setShowZone}
                      helpText="Display the zone name in the success message."
                    />
                    <Checkbox
                      label="Show waitlist form on blocked/not-found zip codes"
                      checked={showWaitlistOnFailure}
                      onChange={setShowWaitlistOnFailure}
                      helpText="Let customers enter their email to join a waitlist when their zip code isn't available."
                    />
                  </BlockStack>
                </Card>

                {/* Custom CSS */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd">
                      Custom CSS
                    </Text>
                    <TextField
                      label="Custom CSS"
                      labelHidden
                      value={customCss}
                      onChange={setCustomCss}
                      multiline={4}
                      placeholder=".zcc-widget { /* your styles */ }"
                      autoComplete="off"
                      helpText="Advanced: add custom CSS to further style the widget."
                    />
                  </BlockStack>
                </Card>
            </BlockStack>

            {/* Live Preview Column */}
            <Box position="sticky" insetBlockStart="400">
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd">
                      Live Preview
                    </Text>
                    <Divider />

                    {/* Preview toggle buttons */}
                    <InlineStack gap="200" wrap>
                      <Button
                        size="slim"
                        pressed={previewState === "idle"}
                        onClick={() => setPreviewState("idle")}
                      >
                        Default
                      </Button>
                      <Button
                        size="slim"
                        pressed={previewState === "success"}
                        onClick={() => setPreviewState("success")}
                      >
                        Success
                      </Button>
                      <Button
                        size="slim"
                        pressed={previewState === "error"}
                        onClick={() => setPreviewState("error")}
                      >
                        Blocked
                      </Button>
                      <Button
                        size="slim"
                        pressed={previewState === "notfound"}
                        onClick={() => setPreviewState("notfound")}
                      >
                        Not Found
                      </Button>
                    </InlineStack>

                    {/* Preview widget */}
                    <Box
                      padding="400"
                      background="bg-surface-secondary"
                      borderRadius="200"
                    >
                      <WidgetPreview />
                    </Box>

                    <Text as="p" tone="subdued" variant="bodySm">
                      This is a preview of how the widget will appear on your
                      storefront. Click the state buttons above to see different
                      scenarios.
                    </Text>
                  </BlockStack>
                </Card>
            </Box>
          </InlineGrid>
        </Layout.Section>
      </Layout>
      </Box>
    </Page>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

input.content:
{% comment %}
  Zip Code Checker — Theme App Extension Block
  Add this block to any section in the Shopify Theme Editor.
  The block automatically connects to your app — no manual configuration needed.
{% endcomment %}

<div
  id="zcc-widget-{{ block.id }}"
  data-shop="{{ shop.permanent_domain }}"
  data-api="{{ app.url }}"
  data-block="{{ block.id }}"
  {{ block.shopify_attributes }}
></div>

<script>
(function () {
  var ROOT_ID = "zcc-widget-{{ block.id }}";
  var container = document.getElementById(ROOT_ID);
  if (!container) return;

  var SHOP = container.dataset.shop;
  var API_BASE = (container.dataset.api || "").replace(/\/$/, "");

  // Fetch widget config, then render
  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
    .then(function (r) { return r.json(); })
    .then(function (cfg) { renderWidget(cfg); })
    .catch(function () { renderWidget({}); });

  function renderWidget(cfg) {
    // Merge with defaults
    var D = {
      position: "inline",
      heading: "Check Delivery Availability",
      placeholder: "Enter your zip code",
      buttonText: "Check",
      successMessage: "Great news! We deliver to your area.",
      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
      notFoundMessage: "This zip code was not found in our system.",
      primaryColor: "#008060",
      successColor: "#008060",
      errorColor: "#D72C0D",
      backgroundColor: "#FFFFFF",
      textColor: "#202223",
      borderRadius: "8",
      showEta: true,
      showZone: false,
      showWaitlistOnFailure: false,
      customCss: "",
    };
    Object.keys(D).forEach(function (k) {
      if (cfg[k] === undefined || cfg[k] === null || cfg[k] === "") cfg[k] = D[k];
    });

    var rad = cfg.borderRadius + "px";
    var WID = "zcc-" + ROOT_ID;

    if (cfg.position === "floating") {
      renderFloating(cfg, WID, rad);
    } else if (cfg.position === "popup") {
      renderPopup(cfg, WID, rad);
    } else {
      renderInline(cfg, WID, rad);
    }
  }

  // ── Shared: inject CSS ──────────────────────────────────────────────────────
  function injectCss(wid, cfg, rad) {
    var css =
      "#" + wid + "{" +
        "background:" + cfg.backgroundColor + ";" +
        "color:" + cfg.textColor + ";" +
        "border-radius:" + rad + ";" +
        "padding:24px;" +
        "border:1px solid #e1e3e5;" +
        "max-width:480px;" +
        "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;" +
        "box-sizing:border-box;" +
      "}" +
      "#" + wid + " *{box-sizing:border-box}" +
      "#" + wid + " .zcc-heading{font-size:16px;font-weight:600;margin:0 0 16px;color:" + cfg.textColor + "}" +
      "#" + wid + " .zcc-row{display:flex;gap:8px;margin-bottom:0}" +
      "#" + wid + " .zcc-input{" +
        "flex:1;padding:10px 12px;border:1px solid #c9cccf;" +
        "border-radius:" + rad + ";font-size:14px;outline:none;" +
        "background:#fafbfb;color:" + cfg.textColor + ";min-width:0" +
      "}" +
      "#" + wid + " .zcc-input:focus{border-color:" + cfg.primaryColor + ";box-shadow:0 0 0 2px " + cfg.primaryColor + "22}" +
      "#" + wid + " .zcc-btn{" +
        "background:" + cfg.primaryColor + ";color:#fff;border:none;" +
        "border-radius:" + rad + ";padding:10px 20px;font-size:14px;" +
        "font-weight:600;cursor:pointer;white-space:nowrap;flex-shrink:0" +
      "}" +
      "#" + wid + " .zcc-btn:hover{opacity:.9}" +
      "#" + wid + " .zcc-btn:disabled{opacity:.6;cursor:not-allowed}" +
      "#" + wid + " .zcc-result{margin-top:12px;padding:12px;border-radius:" + rad + ";font-size:14px;line-height:1.4}" +
      "#" + wid + " .zcc-result.ok{background:" + cfg.successColor + "15;border-left:3px solid " + cfg.successColor + ";color:" + cfg.successColor + "}" +
      "#" + wid + " .zcc-result.fail{background:" + cfg.errorColor + "15;border-left:3px solid " + cfg.errorColor + ";color:" + cfg.errorColor + "}" +
      "#" + wid + " .zcc-meta{margin-top:4px;font-size:13px;opacity:.8}" +
      "#" + wid + " .zcc-wl{margin-top:10px}" +
      "#" + wid + " .zcc-wl-input{" +
        "width:100%;padding:8px 10px;border:1px solid " + cfg.errorColor + "40;" +
        "border-radius:" + rad + ";font-size:13px;margin-bottom:6px;display:block" +
      "}" +
      "#" + wid + " .zcc-wl-btn{" +
        "background:" + cfg.errorColor + ";color:#fff;border:none;" +
        "border-radius:" + rad + ";padding:8px 16px;font-size:13px;" +
        "cursor:pointer;width:100%;font-weight:600" +
      "}" +
      "#" + wid + " .zcc-wl-btn:disabled{opacity:.6;cursor:not-allowed}" +
      (cfg.customCss || "");

    var styleEl = document.createElement("style");
    styleEl.textContent = css;
    document.head.appendChild(styleEl);
  }

  // ── Shared: build widget inner HTML + wire up events ────────────────────────
  function buildWidgetInner(wid, cfg, btnLabel) {
    return (
      '<p class="zcc-heading">' + esc(cfg.heading) + "</p>" +
      '<div class="zcc-row">' +
        '<input class="zcc-input" type="text" id="' + wid + '-inp"' +
          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
        '<button class="zcc-btn" id="' + wid + '-btn" type="button">' + esc(btnLabel) + "</button>" +
      "</div>" +
      '<div id="' + wid + '-res"></div>'
    );
  }

  function wireWidget(wid, cfg, API_BASE, SHOP) {
    var inp = document.getElementById(wid + "-inp");
    var btn = document.getElementById(wid + "-btn");
    var res = document.getElementById(wid + "-res");
    var btnLabel = cfg.buttonText;
    if (!inp || !btn || !res) return;

    function checkZip() {
      var zip = inp.value.trim();
      if (!zip) { inp.focus(); return; }

      btn.disabled = true;
      btn.textContent = "\u2026";
      res.innerHTML = "";

      fetch(
        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
          "&zip=" + encodeURIComponent(zip)
      )
        .then(function (r) { return r.json(); })
        .then(function (data) {
          btn.disabled = false;
          btn.textContent = btnLabel;

          if (data.allowed) {
            var html = '<div class="zcc-result ok">' + esc(data.message);
            if (cfg.showEta && data.eta) {
              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
            }
            if (cfg.showZone && data.zone) {
              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
            }
            html += "</div>";
            res.innerHTML = html;
          } else {
            var html = '<div class="zcc-result fail">' + esc(data.message);
            if (cfg.showWaitlistOnFailure) {
              html +=
                '<div class="zcc-wl">' +
                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Enter email to join waitlist" />' +
                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button">Join Waitlist</button>' +
                "</div>";
            }
            html += "</div>";
            res.innerHTML = html;

            if (cfg.showWaitlistOnFailure) {
              var wBtn = document.getElementById(wid + "-wl-btn");
              if (wBtn) {
                wBtn.addEventListener("click", function () {
                  var emailEl = document.getElementById(wid + "-wl-email");
                  var email = emailEl ? emailEl.value.trim() : "";
                  if (!email) { if (emailEl) emailEl.focus(); return; }
                  joinWaitlist(zip, email, wBtn);
                });
              }
            }
          }
        })
        .catch(function () {
          btn.disabled = false;
          btn.textContent = btnLabel;
          res.innerHTML = '<div class="zcc-result fail">Something went wrong. Please try again.</div>';
        });
    }

    btn.addEventListener("click", checkZip);
    inp.addEventListener("keydown", function (e) {
      if (e.key === "Enter") checkZip();
    });
  }

  function joinWaitlist(zip, email, wBtn) {
    wBtn.disabled = true;
    wBtn.textContent = "Joining\u2026";

    fetch(API_BASE + "/api/waitlist", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ shop: SHOP, zip: zip, email: email }),
    })
      .then(function (r) { return r.json(); })
      .then(function (data) {
        var wlEl = wBtn.closest(".zcc-wl");
        if (data.success) {
          if (wlEl) wlEl.innerHTML =
            '<p style="font-size:13px;margin:6px 0 0">' +
            "\u2713 You\u2019ve been added to the waitlist!" +
            "</p>";
        } else {
          wBtn.disabled = false;
          wBtn.textContent = "Join Waitlist";
        }
      })
      .catch(function () {
        wBtn.disabled = false;
        wBtn.textContent = "Join Waitlist";
      });
  }

  // ── Inline position ─────────────────────────────────────────────────────────
  function renderInline(cfg, WID, rad) {
    injectCss(WID, cfg, rad);
    container.id = WID;
    container.innerHTML = buildWidgetInner(WID, cfg, cfg.buttonText);
    wireWidget(WID, cfg, API_BASE, SHOP);
  }

  // ── Floating position ────────────────────────────────────────────────────────
  function renderFloating(cfg, WID, rad) {
    // The original container becomes invisible (just an anchor)
    container.style.display = "none";

    injectCss(WID, cfg, rad);

    // Additional styles for floating UI
    var floatCss =
      "#" + WID + "-float{position:fixed;bottom:20px;right:20px;z-index:9998;display:flex;flex-direction:column;align-items:flex-end;gap:10px}" +
      "#" + WID + "-panel{" +
        "background:" + cfg.backgroundColor + ";border-radius:" + rad + ";" +
        "box-shadow:0 8px 32px rgba(0,0,0,.18);overflow:hidden;" +
        "transition:opacity .2s,transform .2s;transform-origin:bottom right" +
      "}" +
      "#" + WID + "-panel.zcc-hidden{display:none}" +
      "#" + WID + "-panel .zcc-panel-header{" +
        "display:flex;align-items:center;justify-content:space-between;" +
        "padding:14px 16px 0;margin-bottom:0" +
      "}" +
      "#" + WID + "-panel .zcc-panel-close{" +
        "background:none;border:none;cursor:pointer;font-size:20px;line-height:1;" +
        "color:" + cfg.textColor + ";opacity:.6;padding:0 4px" +
      "}" +
      "#" + WID + "-panel .zcc-panel-close:hover{opacity:1}" +
      "#" + WID + "-trigger{" +
        "background:" + cfg.primaryColor + ";color:#fff;border:none;" +
        "border-radius:50px;padding:12px 20px;font-size:14px;font-weight:600;" +
        "cursor:pointer;box-shadow:0 4px 12px rgba(0,0,0,.2);white-space:nowrap" +
      "}" +
      "#" + WID + "-trigger:hover{opacity:.9}";

    var floatStyle = document.createElement("style");
    floatStyle.textContent = floatCss;
    document.head.appendChild(floatStyle);

    // Build floating shell
    var floatEl = document.createElement("div");
    floatEl.id = WID + "-float";
    floatEl.innerHTML =
      '<div id="' + WID + '-panel" class="zcc-hidden">' +
        '<div class="zcc-panel-header">' +
          '<span style="font-size:13px;font-weight:600;color:' + cfg.textColor + '">Delivery Check</span>' +
          '<button class="zcc-panel-close" id="' + WID + '-close" type="button" aria-label="Close">&times;</button>' +
        '</div>' +
        '<div id="' + WID + '">' +
          buildWidgetInner(WID, cfg, cfg.buttonText) +
        '</div>' +
      '</div>' +
      '<button id="' + WID + '-trigger" type="button">' +
        '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="vertical-align:middle;margin-right:6px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
        esc(cfg.buttonText || "Check Delivery") +
      '</button>';

    document.body.appendChild(floatEl);

    // Wire toggle
    var trigger = document.getElementById(WID + "-trigger");
    var panel = document.getElementById(WID + "-panel");
    var closeBtn = document.getElementById(WID + "-close");

    if (trigger && panel) {
      trigger.addEventListener("click", function () {
        panel.classList.toggle("zcc-hidden");
      });
    }
    if (closeBtn && panel) {
      closeBtn.addEventListener("click", function () {
        panel.classList.add("zcc-hidden");
      });
    }
    // Close on outside click
    document.addEventListener("click", function (e) {
      if (!floatEl.contains(e.target)) {
        if (panel) panel.classList.add("zcc-hidden");
      }
    });

    wireWidget(WID, cfg, API_BASE, SHOP);
  }

  // ── Popup position ───────────────────────────────────────────────────────────
  function renderPopup(cfg, WID, rad) {
    injectCss(WID, cfg, rad);

    var popupCss =
      "#" + WID + "-overlay{" +
        "display:none;position:fixed;inset:0;background:rgba(0,0,0,.55);" +
        "z-index:9999;align-items:center;justify-content:center;padding:16px" +
      "}" +
      "#" + WID + "-overlay.zcc-open{display:flex}" +
      "#" + WID + "-modal{" +
        "background:" + cfg.backgroundColor + ";border-radius:" + rad + ";" +
        "max-width:480px;width:100%;position:relative;" +
        "box-shadow:0 20px 60px rgba(0,0,0,.3)" +
      "}" +
      "#" + WID + "-modal .zcc-modal-close{" +
        "position:absolute;top:10px;right:14px;background:none;border:none;" +
        "font-size:22px;line-height:1;cursor:pointer;color:" + cfg.textColor + ";opacity:.5" +
      "}" +
      "#" + WID + "-modal .zcc-modal-close:hover{opacity:1}" +
      "#" + WID + "-popup-trigger{" +
        "background:" + cfg.primaryColor + ";color:#fff;border:none;" +
        "border-radius:" + rad + ";padding:10px 24px;font-size:14px;font-weight:600;" +
        "cursor:pointer" +
      "}" +
      "#" + WID + "-popup-trigger:hover{opacity:.9}";

    var popupStyle = document.createElement("style");
    popupStyle.textContent = popupCss;
    document.head.appendChild(popupStyle);

    // Trigger button renders in-place (inside the block)
    container.innerHTML =
      '<button id="' + WID + '-popup-trigger" type="button">' +
        esc(cfg.heading) +
      '</button>';

    // Overlay + modal append to body
    var overlay = document.createElement("div");
    overlay.id = WID + "-overlay";
    overlay.innerHTML =
      '<div id="' + WID + '-modal">' +
        '<button class="zcc-modal-close" id="' + WID + '-modal-close" type="button" aria-label="Close">&times;</button>' +
        '<div id="' + WID + '">' +
          buildWidgetInner(WID, cfg, cfg.buttonText) +
        '</div>' +
      '</div>';
    document.body.appendChild(overlay);

    var trigger = document.getElementById(WID + "-popup-trigger");
    var closeBtn = document.getElementById(WID + "-modal-close");
    var modal = document.getElementById(WID + "-modal");

    function openPopup() { overlay.classList.add("zcc-open"); }
    function closePopup() { overlay.classList.remove("zcc-open"); }

    if (trigger) trigger.addEventListener("click", openPopup);
    if (closeBtn) closeBtn.addEventListener("click", closePopup);

    // Close on overlay backdrop click (not modal content)
    overlay.addEventListener("click", function (e) {
      if (e.target === overlay) closePopup();
    });

    // Close on Escape key
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape") closePopup();
    });

    wireWidget(WID, cfg, API_BASE, SHOP);
  }

  function esc(str) {
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function escAttr(str) {
    return String(str).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
  }
})();
</script>

