 198→      });
 199→
 200→      await syncConfigMetafield(admin, resetData);
 201→
 202→      return { success: true, action: "reset" };
 203→    }
 204→
 205→    return null;
 206→  } catch {
 207→    return new Response(JSON.stringify({ error: "Failed to save widget settings." }), {
 208→      status: 500,
 209→      headers: { "Content-Type": "application/json" },
 210→    });
 211→  }
